0, \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ub450\ub294 \uac83\uc774 \uc54c\uae30 \uc26c\uc6b4\uc9c0 \ucc28\ubd84\ud788 \uc548\ub0b4\ud55c\ub2e4.", "tone": "calm"}, {"assetRole": "stage_3", "voicePurpose": "\ube60\uc9c4 \ub9d0\uc744 \ub5a0\uc62c\ub9ac\ub3c4\ub85d \ub3d5\uace0, \uae00 \uc18d \uc5b4\ub5a4 \ubd80\ubd84\uc774 \uaf2d \ub4e4\uc5b4\uac00\uc57c \ud558\ub294\uc9c0 \uc0c1\uae30\uc2dc\ud0a8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\uce5c\uad6c\uc5d0\uac8c \uc124\uba85\ud558\ub4ef\uc774 \u2018\uba3c\uc800, \uadf8\ub2e4\uc74c, \ub9c8\uc9c0\ub9c9\uc73c\ub85c\u2019\ub97c \uc0ac\uc6a9\ud574 \uc790\uc2e0 \uc788\uac8c \ub9d0\ud574 \ubcf4\ub3c4\ub85d \uaca9\ub824\ud55c\ub2e4.", "tone": "reassuring"}]}, "assemblyPolicy": {"contentId": "backend_generated", "stageIds": "backend_generated_by_step", "assetIds": "backend_generated_by_role", "finalPackage": "MissionContent"}, "stageContentDrafts": [{"unitId": "stage_1", "step": 1, "stageId": "stage_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_1", "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uac1c\ub150 \uc5f4\uae30", "studentInstruction": "\uc54c\ub9bc\uc7a5\uc5d0 \uc801\ud78c \ub0b4\uc77c \uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c\uc744 \ubcf4\uba74\uc11c, \uba3c\uc800 \uc5b4\ub5a4 \ub9d0\uc744 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\uc740\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc138\uc694.", "templateJson": {"imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_1", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_1_audio", "assetBundle": {"imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_1", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_1_audio"}, "storyText": "\ub0b4\uc77c \ud559\uad50\uc5d0\uc11c \uccb4\uc721\ub300\ud68c\uac00 \uc5f4\ub9bd\ub2c8\ub2e4. \ub2f4\uc784\uc120\uc0dd\ub2d8\uc740 \ud639\uc2dc \uc900\ube44\ubb3c\uc744 \ube7c\uba39\uc9c0 \uc54a\ub3c4\ub85d \uc624\ub298 \uc54c\ub9bc\uc7a5\uc5d0 \u2018\uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \uc54c\ub9bc\u2019\uc744 \uc801\uc5b4 \uc8fc\uc168\uc5b4\uc694. \ud558\uc9c0\ub9cc \uba87\uba87 \uce5c\uad6c\ub294 \uae00\uc744 \ub300\ucda9 \ubcf4\uace0 \u201c\uadf8\ub0e5 \uccb4\uc721\ubcf5\ub9cc \ucc59\uae30\uba74 \ub418\uc9c0\u201d\ub77c\uace0 \ub9d0\ud574\uc694.", "missionText": "\uc54c\ub9bc\uc7a5\uc744 \uc704\uc5d0\uc11c \uc544\ub798\ub85c \ud55c \ubc88\uc5d0 \ud6d1\uc5b4\ubcf4\uae30\ubcf4\ub2e4, \u2018\uc5b8\uc81c\u2019, \u2018\ubb34\uc5c7\uc744\u2019, \u2018\uc5b4\ub5bb\uac8c\u2019 \uc900\ube44\ud574\uc57c \ud558\ub294\uc9c0 \uc54c\ub824 \uc8fc\ub294 \ub9d0\uc744 \uba3c\uc800 \ucc3e\uc73c\uba74 \uc900\ube44\ubb3c\uc744 \ub354 \ub610\ub837\ud558\uac8c \uae30\uc5b5\ud560 \uc218 \uc788\uc5b4\uc694. \uacf5\ucc45\uc758 \uc54c\ub9bc\uc7a5\uc744 \ubcf4\uba74\uc11c \uc5b4\ub5a4 \ub0b1\ub9d0\uc5d0 \uba3c\uc800 \ub208\uae38\uc744 \uc8fc\uba74 \uc88b\uc744\uc9c0 \ub5a0\uc62c\ub824 \ubd05\uc2dc\ub2e4.", "sourceTextLines": ["\uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \uc54c\ub9bc", "5\uc6d4 \u25cb\uc77c(\u25cb\uc694\uc77c) \ub0b4\uc77c\uc740 \uccb4\uc721\ub300\ud68c\uac00 \uc788\uc2b5\ub2c8\ub2e4.", "\uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654\ub97c \ucc59\uaca8 \uc635\ub2c8\ub2e4.", "\ubb3c \ud55c \ubcd1\uacfc \uc774\ub984\ud45c\ub97c \uac00\uc838\uc635\ub2c8\ub2e4."], "sceneTextLines": ["\ucc45\uc0c1 \uc704 \uacf5\ucc45\uc5d0 \u2018\uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \uc54c\ub9bc\u2019 \uc81c\ubaa9\uacfc \ub0a0\uc9dc, \uc900\ube44\ubb3c \ubb38\uc7a5\uc774 \uc9e7\uac8c \uc801\ud600 \uc788\uace0, \ud559\uc0dd \uc190\uc774 \ud55c \ubb38\uc7a5\uc744 \uac00\ub9ac\ud0a4\uace0 \uc788\ub2e4."]}, "realtimeSpec": null, "imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_1", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_1_audio", "visualSpec": {"unitId": "visual_stage_1", "assetRole": "stage_1", "step": 1, "visualPurpose": "\ud559\uc0dd\uc774 \uc54c\ub9bc\uc7a5\uc744 \uc9c1\uc811 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uc0c1\ud669\uc744 \uac15\uc870\ud574, \uae00 \uc18d \uc911\uc694\ud55c \ub2e8\uc11c\ub97c \ucc3e\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc900\ub2e4.", "sceneSummary": "\ucc45\uc0c1\uc5d0 \uc549\uc740 \ud559\uc0dd\uc774 \uacf5\ucc45\uc744 \ud3bc\uccd0 \uc54c\ub9bc\uc7a5 \uae00\uc744 \uc77d\uace0 \uc788\uace0, \uc5f0\ud544\ub85c \uba87\uba87 \ub2e8\uc5b4\ub97c \uac00\ub9ac\ud0a4\ub824\ub294 \ubaa8\uc2b5\uc774\ub2e4.", "primaryEvidenceObject": "\uc54c\ub9bc\uc7a5 \uae00\uc774 \uc801\ud78c \uacf5\ucc45 \ud398\uc774\uc9c0", "evidenceLocation": "\ud559\uc0dd \ucc45\uc0c1 \uc704 \uc911\uc559", "mustShow": ["\ub098\ubb34 \ucc45\uc0c1 \uc704\uc5d0 \ud3bc\uccd0\uc9c4 \uacf5\ucc45", "\uacf5\ucc45 \ud55c \ud398\uc774\uc9c0 \uc0c1\ub2e8\uc758 \u2018\uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \uc54c\ub9bc\u2019 \uc81c\ubaa9", "\uadf8 \uc544\ub798\uc5d0 \uc9e7\uac8c \uc801\ud78c \ub0a0\uc9dc\uc640 \uc900\ube44\ubb3c \ubb38\uc7a5\ub4e4", "\uc5f0\ud544\uc744 \ub4e0 \ud559\uc0dd \uc190\uc774 \ud2b9\uc815 \ub2e8\uc5b4 \ucabd\uc744 \uac00\ub9ac\ud0a4\ub294 \ubaa8\uc2b5"], "allowedSceneText": ["\uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \uc54c\ub9bc", "5\uc6d4 \u25cb\uc77c(\u25cb\uc694\uc77c)", "\uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654\ub97c \ucc59\uaca8 \uc635\ub2c8\ub2e4.", "\ubb3c \ud55c \ubcd1\uacfc \uc774\ub984\ud45c\ub97c \uac00\uc838\uc635\ub2c8\ub2e4."], "doNotRenderText": ["problem", "choices", "answer", "feedback"], "composition": "\uc704\uc5d0\uc11c \uc57d\uac04 \ube44\uc2a4\ub4ec\ud788 \ub0b4\ub824\ub2e4\ubcf4\ub294 \uad6c\ub3c4\ub85c, \uacf5\ucc45\uacfc \uc190, \uae00\uc790\uac00 \ub3d9\uc2dc\uc5d0 \ub610\ub837\uc774 \ubcf4\uc774\uac8c \ubc30\uce58\ud55c\ub2e4."}}, {"unitId": "stage_2", "step": 2, "stageId": "stage_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_2", "stageRole": "basic_problem", "templateType": "sequence_ordering", "studentTitle": "\ubb38\uc81c 1", "studentInstruction": "\uc54c\ub9bc\uc7a5\uc5d0\uc11c \uc798\ub77c \ub193\uc740 \uc138 \ubb38\uc7a5\uc744 \uc77d\uc5b4 \ubcf4\uace0, \uce5c\uad6c\uc5d0\uac8c \uc54c\ub824 \uc904 \ub54c \uc54c\uae30 \uc88b\uc740 \uc21c\uc11c\ub300\ub85c \ucc28\ub840\ub97c \uc815\ud574 \ubcf4\uc138\uc694.", "templateJson": {"imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_2", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_2_audio", "assetBundle": {"imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_2", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_2_audio"}, "question": "\ub0b4\uc77c \uccb4\uc721\ub300\ud68c\ub97c \ubaa8\ub974\ub294 \uce5c\uad6c\uc5d0\uac8c \uc900\ube44\ubb3c\uc744 \uc54c\ub824 \uc904 \ub54c, \uc544\ub798 \uc138 \ubb38\uc7a5\uc744 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ub9d0\ud558\uba74 \uac00\uc7a5 \uc54c\uae30 \uc88b\uc744\uae4c\uc694? \uc54c\ub9de\uc740 \uc21c\uc11c\ub300\ub85c \uc904\uc744 \uc138\uc6cc \ubcf4\uc138\uc694.", "cards": [{"id": "c1", "text": "\uba3c\uc800 \uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654\ub97c \ucc59\uae41\ub2c8\ub2e4."}, {"id": "c2", "text": "\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc774\ub984\ud45c\ub97c \uac00\ubc29\uc5d0 \ub123\uc2b5\ub2c8\ub2e4."}, {"id": "c3", "text": "\uadf8\ub2e4\uc74c \ubb3c \ud55c \ubcd1\uc744 \uc900\ube44\ud569\ub2c8\ub2e4."}], "answerOrder": ["c1", "c3", "c2"], "correctFeedback": "\uc798\ud588\uc5b4\uc694. \uba3c\uc800 \ubab8\uc5d0 \uc785\uc744 \uac83(\uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654)\uc744 \ub9d0\ud558\uace0, \uadf8\ub2e4\uc74c \ub9c8\uc2e4 \ubb3c, \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc774\ub984\ud45c \uc21c\uc11c\ub85c \ub9d0\ud574 \uc8fc\uba74 \ub4e3\ub294 \uce5c\uad6c\ub3c4 \uc900\ube44 \uc21c\uc11c\ub97c \uc27d\uac8c \ub5a0\uc62c\ub9b4 \uc218 \uc788\uc5b4\uc694.", "wrongFeedback": "\uc870\uae08 \ud5f7\uac08\ub9b4 \uc218 \uc788\uc5b4\uc694. \ub0b4\uc77c \uc900\ube44\ud560 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uba70 \u2018\ubb34\uc5c7\uc744 \uc81c\uc77c \uba3c\uc800 \ucc59\uae30\uba74 \uc88b\uc744\uc9c0\u2019, \u2018\uadf8\ub2e4\uc74c, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ubb34\uc5c7\uc744 \ub123\ub294\uc9c0\u2019 \uc0dd\uac01\ud558\uba74\uc11c \uc21c\uc11c\ub97c \ub2e4\uc2dc \uc815\ud574 \ubcf4\uc138\uc694.", "sourceTextLines": ["\uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654\ub97c \ucc59\uaca8 \uc635\ub2c8\ub2e4.", "\ubb3c \ud55c \ubcd1\uc744 \uc900\ube44\ud569\ub2c8\ub2e4.", "\uc774\ub984\ud45c\ub97c \uac00\ubc29\uc5d0 \ub123\uc2b5\ub2c8\ub2e4."], "sceneTextLines": ["\ucc45\uc0c1 \uc704\uc5d0 \u2018\uba3c\uc800 \uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654\ub97c \ucc59\uae41\ub2c8\ub2e4.\u2019, \u2018\uadf8\ub2e4\uc74c \ubb3c \ud55c \ubcd1\uc744 \uc900\ube44\ud569\ub2c8\ub2e4.\u2019, \u2018\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc774\ub984\ud45c\ub97c \uac00\ubc29\uc5d0 \ub123\uc2b5\ub2c8\ub2e4.\u2019\ub77c\uace0 \uc801\ud78c \uce74\ub4dc \uc138 \uc7a5\uc774 \ud769\uc5b4\uc838 \uc788\ub2e4."]}, "realtimeSpec": null, "imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_2", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_2_audio", "visualSpec": {"unitId": "visual_stage_2", "assetRole": "stage_2", "step": 2, "visualPurpose": "\uc54c\ub9bc\uc7a5 \uc18d \ud575\uc2ec \ub2e8\uc11c \ubb38\uc7a5\ub4e4\uc744 \uc798\ub77c \ub0b8 \uce74\ub4dc\ucc98\ub7fc \ub610\ub837\ud558\uac8c \ubcf4\uc5ec \uc8fc\uc5b4, \uc21c\uc11c \uc815\ub9ac \ud65c\ub3d9\uc758 \uadfc\uac70 \uc790\ub8cc\ub85c \uc0bc\uac8c \ud55c\ub2e4.", "sceneSummary": "\uc54c\ub9bc\uc7a5\uc5d0\uc11c \uc624\ub9b0 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \uc9e7\uc740 \ubb38\uc7a5 \uc870\uac01 \uce74\ub4dc\ub4e4\uc774 \ucc45\uc0c1 \uc704\uc5d0 \ub193\uc5ec \uc788\uace0, \uc606\uc5d0\uc11c \ud559\uc0dd \uc190\uc774 \uce74\ub4dc\ub97c \uc62e\uae30\ub824\ub294 \uc7a5\uba74.", "primaryEvidenceObject": "\uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \ubb38\uc7a5 \uc870\uac01 \uce74\ub4dc\ub4e4", "evidenceLocation": "\ucc45\uc0c1 \uc704 \uc911\uc559", "mustShow": ["\ub098\ubb34 \ucc45\uc0c1 \uc704", "\u2018\uba3c\uc800 \uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654\ub97c \ucc59\uae41\ub2c8\ub2e4.\u2019 \uac19\uc740 \uc9e7\uc740 \ubb38\uc7a5\uc774 \uc801\ud78c \uc885\uc774 \uc870\uac01\ub4e4", "\u2018\uadf8\ub2e4\uc74c \ubb3c \ud55c \ubcd1\uc744 \uc900\ube44\ud569\ub2c8\ub2e4.\u2019\uc640 \ube44\uc2b7\ud55c \uc885\uc774 \uc870\uac01", "\u2018\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc774\ub984\ud45c\ub97c \uac00\ubc29\uc5d0 \ub123\uc2b5\ub2c8\ub2e4.\u2019\uc640 \ube44\uc2b7\ud55c \uc885\uc774 \uc870\uac01", "\uce74\ub4dc\ub97c \uc7a1\uace0 \uc788\ub294 \ud559\uc0dd\uc758 \uc190"], "allowedSceneText": ["\uba3c\uc800 \uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654\ub97c \ucc59\uae41\ub2c8\ub2e4.", "\uadf8\ub2e4\uc74c \ubb3c \ud55c \ubcd1\uc744 \uc900\ube44\ud569\ub2c8\ub2e4.", "\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc774\ub984\ud45c\ub97c \uac00\ubc29\uc5d0 \ub123\uc2b5\ub2c8\ub2e4."], "doNotRenderText": ["problem", "choices", "answer", "feedback"], "composition": "\uce74\ub4dc\ub4e4\uc774 \ud55c\ub208\uc5d0 \ub4e4\uc5b4\uc624\ub3c4\ub85d \uc704\uc5d0\uc11c \ub0b4\ub824\ub2e4\ubcf8 \ud074\ub85c\uc988\uc5c5 \uad6c\ub3c4\ub85c \uad6c\uc131\ud558\uace0, \ubb38\uc7a5\ub4e4\uc774 \uc77d\ud788\ub3c4\ub85d \uc5ec\uc720 \uc788\uac8c \ubc30\uce58\ud55c\ub2e4."}}, {"unitId": "stage_3", "step": 3, "stageId": "stage_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_3", "stageRole": "applied_problem", "templateType": "blank_fill", "studentTitle": "\ubb38\uc81c 2", "studentInstruction": "\ube44\uc2b7\ud55c \uc54c\ub9bc\uc7a5 \ubb38\uc7a5\uc744 \uc77d\uace0, \ube48\uce78\uc5d0 \ub4e4\uc5b4\uac08 \uc54c\ub9de\uc740 \ub9d0\uc744 \uace8\ub77c \ub123\uc5b4 \ubcf4\uc138\uc694.", "templateJson": {"imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_3", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_3_audio", "assetBundle": {"imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_3", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_3_audio"}, "question": "\ub2e4\uc74c \uc54c\ub9bc\uc7a5 \ubb38\uc7a5\uc5d0\uc11c \ube48\uce78\uc5d0 \ub4e4\uc5b4\uac08 \uc54c\ub9de\uc740 \ub9d0\uc744 \uace8\ub77c \ubb38\uc7a5\uc744 \uc644\uc131\ud574 \ubcf4\uc138\uc694.\n\n\"5\uc6d4 \u25cb\uc77c \uc54c\ub9bc\n\ub0b4\uc77c\uc740 __ \uc785\ub2c8\ub2e4.\n\uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654, \ubb3c \ud55c \ubcd1, \uc774\ub984\ud45c\ub97c __.\"", "sentence": "5\uc6d4 \u25cb\uc77c \uc54c\ub9bc / \ub0b4\uc77c\uc740 __ \uc785\ub2c8\ub2e4. / \uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654, \ubb3c \ud55c \ubcd1, \uc774\ub984\ud45c\ub97c __.", "tiles": ["\uccb4\uc721\ub300\ud68c", "\ucc59\uaca8 \uc635\ub2c8\ub2e4", "\ud559\uad50\ucd95\uc81c"], "acceptedAnswers": [{"answer": "\uccb4\uc721\ub300\ud68c, \ucc59\uaca8 \uc635\ub2c8\ub2e4"}, {"answer": "\uccb4\uc721\ub300\ud68c , \ucc59\uaca8 \uc635\ub2c8\ub2e4"}], "correctFeedback": "\uc88b\uc544\uc694. \u2018\ub0b4\uc77c\uc740 \uccb4\uc721\ub300\ud68c\uc785\ub2c8\ub2e4.\u2019\uc640 \u2018\uc900\ube44\ubb3c\uc744 \ucc59\uaca8 \uc635\ub2c8\ub2e4.\u2019\ub77c\ub294 \ubb38\uc7a5\uc774 \uc788\uc5b4\uc57c \uce5c\uad6c\uac00 \uc5b8\uc81c \ubb34\uc5c7\uc744 \uc900\ube44\ud574\uc57c \ud558\ub294\uc9c0 \ub610\ub837\ud558\uac8c \uc54c \uc218 \uc788\uc5b4\uc694.", "wrongFeedback": "\ub2e4\uc2dc \ud55c \ubc88 \uc0dd\uac01\ud574 \ubcfc\uae4c\uc694? \uc54c\ub9bc\uc7a5\uc5d0\uc11c \uaf2d \uc54c\ub824 \uc8fc\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \u2018\ubb34\uc2a8 \ub0a0\uc778\uc9c0\u2019\uc640 \u2018\ubb34\uc5c7\uc744 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub294\uc9c0\u2019\uc608\uc694. \uadf8 \ub73b\uc5d0 \uc5b4\uc6b8\ub9ac\ub294 \ub9d0\uc744 \uace8\ub77c \ub450 \ube48\uce78\uc5d0 \ucc28\ub840\ub300\ub85c \ub123\uc5b4 \ubcf4\uc138\uc694.", "sourceTextLines": ["5\uc6d4 \u25cb\uc77c \uc54c\ub9bc", "\ub0b4\uc77c\uc740 \uccb4\uc721\ub300\ud68c\uc785\ub2c8\ub2e4.", "\uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654, \ubb3c \ud55c \ubcd1, \uc774\ub984\ud45c\ub97c \ucc59\uaca8 \uc635\ub2c8\ub2e4."], "sceneTextLines": ["\uacf5\ucc45 \ud55c \ud398\uc774\uc9c0\uc5d0 \u20185\uc6d4 \u25cb\uc77c \uc54c\ub9bc\u2019\uacfc \uccb4\uc721\ub300\ud68c \uc900\ube44 \ubb38\uc7a5\uc774 \uc801\ud600 \uc788\uace0, \uba87\uba87 \uc911\uc694\ud55c \ub2e8\uc5b4\uc5d0 \ubc11\uc904\uc774 \uadf8\uc5b4\uc838 \uc788\ub2e4."]}, "realtimeSpec": null, "imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_3", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_3_audio", "visualSpec": {"unitId": "visual_stage_3", "assetRole": "stage_3", "step": 3, "visualPurpose": "\ube44\uc2b7\ud55c \uc54c\ub9bc\uc7a5 \ubb38\uc7a5\uc5d0\uc11c \uc77c\ubd80 \ub2e8\uc11c\uac00 \ube48\uce78\ucc98\ub7fc \ub290\uaef4\uc9c0\ub3c4\ub85d, \ubc11\uc904 \uce60 \ubd80\ubd84\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc7a5\uba74\uc744 \uc81c\uacf5\ud55c\ub2e4.", "sceneSummary": "\ub2e4\ub978 \ub0a0\uc758 \uc54c\ub9bc\uc7a5\ucc98\ub7fc \ubcf4\uc774\ub294 \uacf5\ucc45 \ud398\uc774\uc9c0 \uc704\uc5d0 \uc5f0\ud544\uc774 \ub193\uc5ec \uc788\uace0, \uba87\uba87 \uc911\uc694\ud55c \ub0b1\ub9d0 \uc544\ub798\uc5d0 \ubc11\uc904\uc774 \uadf8\uc5b4\uc838 \uc788\ub2e4.", "primaryEvidenceObject": "\uc911\uc694 \ub2e8\uc5b4\uc5d0 \ubc11\uc904\uc774 \uadf8\uc5b4\uc9c4 \uc54c\ub9bc\uc7a5 \ubb38\uc7a5", "evidenceLocation": "\uacf5\ucc45 \ud398\uc774\uc9c0 \uc911\uc559", "mustShow": ["\uacf5\ucc45 \ud55c \ud398\uc774\uc9c0\uc5d0 \uc801\ud78c \uc9e7\uc740 \uc548\ub0b4\ubb38", "\ub450\uc138 \uc904 \ubb38\uc7a5\uc5d0\uc11c \uba87\uba87 \ub2e8\uc5b4 \uc544\ub798\uc5d0 \ubc11\uc904\uc774 \uadf8\uc5b4\uc9c4 \ubaa8\uc2b5", "\uc606\uc5d0 \ub193\uc778 \uc5f0\ud544", "\ub0a0\uc9dc \uc904\uacfc \uc900\ube44\ubb3c \ub610\ub294 \ud574\uc57c \ud560 \uc77c \ubb38\uc7a5\ub4e4"], "allowedSceneText": ["5\uc6d4 \u25cb\uc77c \uc54c\ub9bc", "\ud559\uae09 \ud68c\ube44\ub97c \uac00\uc838\uc635\ub2c8\ub2e4.", "\uc900\ube44\ubb3c\uc744 \uaf2d \ud655\uc778\ud569\ub2c8\ub2e4."], "doNotRenderText": ["problem", "choices", "answer", "feedback"], "composition": "\ucc45\uc0c1 \uc704\ub97c \uc704\uc5d0\uc11c \ub0b4\ub824\ub2e4\ubcf4\uba70, \uae00\uc904\uacfc \ubc11\uc904\uc774 \uc911\uc2ec\uc774 \ub418\ub3c4\ub85d \ub2e8\uc21c\ud558\uac8c \ubc30\uce58\ud55c\ub2e4."}}, {"unitId": "stage_4", "step": 4, "stageId": "stage_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_4", "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "studentInstruction": "\ub0b4\uc77c \uc900\ube44\ubb3c\uc744 \uc798 \ubaa8\ub974\ub294 \uce5c\uad6c\uc5d0\uac8c \uc54c\ub824 \uc900\ub2e4\uace0 \uc0dd\uac01\ud558\uace0, \uc54c\ub9bc\uc7a5\uc5d0\uc11c \ucc3e\uc740 \ub0b4\uc6a9\uc744 2~3\ub2e8\uacc4\ub85c \ub610\ubc15\ub610\ubc15 \ub9d0\ud574 \ubcf4\uc138\uc694.", "templateJson": {"imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_4_realtime", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_4_realtime", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_4_realtime_audio"}, "situationText": "\ubc29\uacfc \ud6c4 \uad50\uc2e4\uc5d0\uc11c \uce5c\uad6c\uac00 \uac00\ubc29\uc744 \uc815\ub9ac\ud558\ub2e4\uac00 \"\ub0b4\uc77c \uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \ubb50\uc600\uc9c0?\"\ub77c\uace0 \ubb3b\uace0 \uc788\uc5b4\uc694. \ub108\ub294 \uc54c\ub9bc\uc7a5\uc744 \ub5a0\uc62c\ub9ac\uba70 \ub0b4\uc77c \ubb34\uc5c7\uc744 \uc5b4\ub5bb\uac8c \uc900\ube44\ud574\uc57c \ud558\ub294\uc9c0 \uc54c\ub824 \uc8fc\ub824\uace0 \ud574\uc694.", "practicePrompt": "\uba3c\uc800 \ub0b4\uc77c\uc774 \ubb34\uc2a8 \ub0a0\uc778\uc9c0 \ub9d0\ud558\uace0, \uadf8\ub2e4\uc74c \ubb34\uc5c7\uc744 \ucc59\uaca8\uc57c \ud558\ub294\uc9c0, \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc5b4\ub514\uc5d0 \ub123\uc5b4 \ub450\uba74 \uc88b\uc740\uc9c0\uae4c\uc9c0 2~3\ubb38\uc7a5\uc73c\ub85c \ub098\ub204\uc5b4 \ub9d0\ud574 \ubcf4\uc138\uc694.", "sourceTextLines": ["\uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \uc54c\ub9bc", "5\uc6d4 \u25cb\uc77c(\u25cb\uc694\uc77c) \ub0b4\uc77c\uc740 \uccb4\uc721\ub300\ud68c\uac00 \uc788\uc2b5\ub2c8\ub2e4.", "\uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654\ub97c \ucc59\uaca8 \uc635\ub2c8\ub2e4.", "\ubb3c \ud55c \ubcd1\uacfc \uc774\ub984\ud45c\ub97c \uac00\uc838\uc635\ub2c8\ub2e4."], "sceneTextLines": ["\ub450 \uce5c\uad6c\uac00 \ucc45\uc0c1 \uc606\uc5d0\uc11c \uac00\ubc29\uc744 \uc815\ub9ac\ud558\uace0 \uc788\uace0, \ud55c \ud559\uc0dd\uc774 \uacf5\ucc45\uc744 \ud3bc\uccd0 \uc54c\ub9bc\uc7a5 \ub0b4\uc6a9\uc744 \ubcf4\uc5ec \uc8fc\uba70 \uc124\uba85\ud558\uace0 \uc788\ub2e4."]}, "realtimeSpec": {"id": "rt_spec_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b", "stageId": "stage_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ub0b4\uc77c \uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \ub9d0\ud574 \ubcf4\uae30", "situationText": "\uce5c\uad6c\uac00 \ub0b4\uc77c \uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c\uc774 \ud5f7\uac08\ub824 \ud560 \ub54c, \uc54c\ub9bc\uc7a5\uc744 \ub5a0\uc62c\ub9ac\uba70 \uc900\ube44\ubb3c\uc744 2~3\ub2e8\uacc4\ub85c \ub098\ub204\uc5b4 \uc124\uba85\ud574 \ubcf4\ub294 \uc5f0\uc2b5\uc785\ub2c8\ub2e4.", "aiRole": "\ub0b4\uc77c \uc900\ube44\ubb3c\uc774 \uad81\uae08\ud55c \uac19\uc740 \ubc18 \uce5c\uad6c", "openingLine": "\ub0b4\uc77c \uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c\uc774 \uc798 \uae30\uc5b5\uc774 \uc548 \ub098. \uc54c\ub9bc\uc7a5 \uc0dd\uac01\ud558\uba74\uc11c \uba3c\uc800, \uadf8\ub2e4\uc74c, \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ubb34\uc5c7\uc744 \ucc59\uaca8\uc57c \ud558\ub294\uc9c0 \uc9e7\uac8c\ub9cc \uc54c\ub824 \uc904\ub798?", "studentGoal": "\uc54c\ub9bc\uc7a5\uc5d0\uc11c \ucc3e\uc740 \ud575\uc2ec \ub2e8\uc11c(\ub0b4\uc77c \uccb4\uc721\ub300\ud68c, \uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654, \ubb3c \ud55c \ubcd1, \uc774\ub984\ud45c)\ub97c \ub5a0\uc62c\ub9ac\uba70 \u2018\uba3c\uc800, \uadf8\ub2e4\uc74c, \ub9c8\uc9c0\ub9c9\uc73c\ub85c\u2019 \uac19\uc740 \ub9d0\uc744 \uc0ac\uc6a9\ud574 2~3\ubb38\uc7a5\uc73c\ub85c \uc900\ube44\ubb3c\uc744 \ub610\ub837\ud558\uac8c \uc124\uba85\ud574 \ubcf8\ub2e4.", "rubric": [{"id": "r1", "label": "\ub0b4\uc77c\uc774 \uccb4\uc721\ub300\ud68c\ub77c\ub294 \ub9d0\uc744 \uba3c\uc800 \uc54c\ub824 \uc900\ub2e4.", "required": true}, {"id": "r2", "label": "\uccb4\uc721\ubcf5\uacfc \uc6b4\ub3d9\ud654, \ubb3c \ud55c \ubcd1, \uc774\ub984\ud45c\ucc98\ub7fc \ucc59\uaca8\uc57c \ud560 \uc900\ube44\ubb3c\uc744 \ud55c \ubc88\uc5d0 \ubb36\uc5b4\uc11c \ub9d0\ud574 \uc900\ub2e4.", "required": true}, {"id": "r3", "label": "\u2018\uba3c\uc800\u2019, \u2018\uadf8\ub2e4\uc74c\u2019, \u2018\ub9c8\uc9c0\ub9c9\uc73c\ub85c\u2019 \uac19\uc740 \uc21c\uc11c \ub9d0\uc744 \uc0ac\uc6a9\ud574 \ub2e8\uacc4\ub97c \ub098\ub204\uc5b4 \ub9d0\ud55c\ub2e4.", "required": false}, {"id": "r4", "label": "2~3\uac1c\uc758 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub610\ubc15\ub610\ubc15 \uc774\uc57c\uae30\ud55c\ub2e4.", "required": false}, {"id": "r5", "label": "\uac00\ubc29\uc5d0 \ubbf8\ub9ac \ub123\uc5b4 \ub450\ub294 \ub4f1 \uc5b4\ub5bb\uac8c \uc900\ube44\ud558\uba74 \uc88b\uc740\uc9c0 \ud55c \ubb38\uc7a5 \uc815\ub3c4 \ub367\ubd99\uc778\ub2e4.", "required": false}], "allowedFeedback": ["\ud559\uc0dd\uc774 \uc774\ubbf8 \ub9d0\ud574 \uc900 \uc911\uc694\ud55c \ub0b4\uc6a9\uc744 \uba3c\uc800 \uce6d\ucc2c\ud558\uace0, \ube60\uc9c4 \uc900\ube44\ubb3c\uc774\ub098 \ub2e8\uacc4\ub97c \ud55c \uac00\uc9c0\uc529 \uc9c8\ubb38\uc73c\ub85c \ub5a0\uc62c\ub9ac\uac8c \ub3c4\uc640\uc90d\ub2c8\ub2e4.", "\ud559\uc0dd\uc774 \uc21c\uc11c \ub9d0\uc744 \ube7c\uba39\uc5c8\uc744 \ub54c, \uc9c0\uae08\uae4c\uc9c0 \ub9d0\ud55c \ub0b4\uc6a9\uc744 \uc778\uc815\ud574 \uc8fc\uace0 \u2018\uba3c\uc800, \uadf8\ub2e4\uc74c, \ub9c8\uc9c0\ub9c9\uc73c\ub85c\u2019 \uc911 \ud558\ub098\ub97c \ubd99\uc5ec \ub2e4\uc2dc \ub9d0\ud574 \ubcf4\ub3c4\ub85d \ubd80\ub4dc\ub7fd\uac8c \uc81c\uc548\ud569\ub2c8\ub2e4.", "\ud559\uc0dd\uc774 \ub9d0\uc744 \uba48\ucd94\uba74 \uc9c0\uae08\uae4c\uc9c0 \uc798\ud55c \ubd80\ubd84\uc744 \uc9da\uc5b4 \uc8fc\uace0, \ub0a8\uc740 \ud55c \ub2e8\uacc4\ub9cc \ub354 \ub9d0\ud574 \ubcf4\ub3c4\ub85d \ucc9c\ucc9c\ud788 \uc774\ub055\ub2c8\ub2e4."], "forbidden": ["\uc815\ub2f5 \ubb38\uc7a5\uc744 \uadf8\ub300\ub85c \ub300\uc2e0 \ub9d0\ud574 \uc8fc\uc9c0 \uc54a\uae30", "\uc798\ubabb \ub9d0\ud588\ub2e4\uace0\ub9cc \uc9c0\uc801\ud558\uba70 \uc704\ucd95\uc2dc\ud0a4\uc9c0 \uc54a\uae30", "\uc7ac\ucd09\ud558\ub294 \ub9d0\ud22c\ub85c \ud559\uc0dd \ub9d0\uc744 \uc790\ub974\uac70\ub098 \ub108\ubb34 \ube60\ub974\uac8c \uc9c8\ubb38\ud558\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 180, "postPracticeReflection": ["\ubc29\uae08 \uce5c\uad6c\uc5d0\uac8c \uc124\uba85\ud560 \ub54c, \ub0b4\uac00 \uc81c\uc77c \uba3c\uc800 \uc54c\ub824 \uc900 \uc911\uc694\ud55c \ub9d0\uc740 \ubb34\uc5c7\uc774\uc5c8\ub098\uc694?", "\ub2e4\uc74c\uc5d0 \ub2e4\uc2dc \uc124\uba85\ud55c\ub2e4\uba74, \u2018\uba3c\uc800, \uadf8\ub2e4\uc74c, \ub9c8\uc9c0\ub9c9\uc73c\ub85c\u2019 \uc911 \uc5b4\ub5a4 \ub9d0\uc744 \ub354 \uc368 \ubcf4\uace0 \uc2f6\uc740\uc9c0 \ub5a0\uc62c\ub824 \ubcf4\uc138\uc694."]}, "imageAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_4_realtime", "audioAssetId": "asset_content_student_\ucd5c\ud558\ub298_676c91bc_1778584359_ae03997b_stage_4_realtime_audio", "visualSpec": {"unitId": "visual_stage_4_realtime", "assetRole": "stage_4_realtime", "step": 4, "visualPurpose": "\ud559\uc0dd\uc774 \uc2e4\uc81c\ub85c \uce5c\uad6c\uc5d0\uac8c \ub0b4\uc77c \uc900\ube44\ubb3c\uc744 \ub2e8\uacc4\ubcc4\ub85c \uc124\uba85\ud558\ub294 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4.", "sceneSummary": "\ubc29\uacfc \ud6c4 \uad50\uc2e4\uc5d0\uc11c \ub450 \uce5c\uad6c\uac00 \uac00\ubc29\uc744 \uc815\ub9ac\ud558\uace0 \uc788\uace0, \ud55c \ud559\uc0dd\uc774 \uacf5\ucc45\uc744 \ud3bc\uccd0 \ubcf4\uc774\uba70 \ub2e4\ub978 \uce5c\uad6c\uc5d0\uac8c \ub0b4\uc77c \uc900\ube44\ubb3c\uc744 \uc124\uba85\ud574 \uc8fc\ub294 \ubaa8\uc2b5.", "primaryEvidenceObject": "\uc54c\ub9bc\uc7a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uacf5\ucc45\uacfc \uc900\ube44\ubb3c\uc744 \ucc59\uae30\ub294 \ud589\ub3d9", "evidenceLocation": "\ub450 \ud559\uc0dd \uc0ac\uc774 \ucc45\uc0c1 \uc704\uc640 \uac00\ubc29 \uadfc\ucc98", "mustShow": ["\ucc45\uc0c1 \uc606\uc5d0 \uc120 \ub450 \uba85\uc758 \ucd08\ub4f1\ud559\uc0dd", "\ud55c \ud559\uc0dd \uc190\uc5d0 \ub4e4\ub9b0 \uacf5\ucc45(\uc54c\ub9bc\uc7a5 \ud398\uc774\uc9c0\ub97c \ud3bc\uce5c \ubaa8\uc2b5)", "\ub2e4\ub978 \ud559\uc0dd \ucc45\uc0c1 \uc704 \ub610\ub294 \uac00\ubc29 \uc606\uc758 \uccb4\uc721\ubcf5, \uc6b4\ub3d9\ud654, \ubb3c\ubcd1, \uc774\ub984\ud45c \uac19\uc740 \uc900\ube44\ubb3c\ub4e4", "\uad50\uc2e4 \ub0b4\ubd80 \ubc30\uacbd"], "allowedSceneText": ["\uccb4\uc721\ub300\ud68c \uc900\ube44\ubb3c \uc54c\ub9bc"], "doNotRenderText": ["problem", "choices", "answer", "feedback"], "composition": "\ub450 \ud559\uc0dd\uacfc \ucc45\uc0c1, \uacf5\ucc45\uc774 \ud55c \ud654\uba74\uc5d0 \ub4e4\uc5b4\uc624\ub3c4\ub85d \uc911\uac04 \uac70\ub9ac\uc5d0\uc11c \uc7a1\uace0, \uacf5\ucc45 \uc81c\ubaa9\uacfc \uc900\ube44\ubb3c\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\uc774\uac8c \uad6c\uc131\ud55c\ub2e4."}}], "assemblyNotes": ["\ubc31\uc5d4\ub4dc\uac00 content/stage/asset id\ub97c \uacb0\uc815\uc801\uc73c\ub85c \uc7ac\uc791\uc131\ud588\uc2b5\ub2c8\ub2e4.", "\uc774\ubbf8\uc9c0 provider prompt\ub294 stageVisualSpecs\uc640 templateJson\uc744 \uc870\ud569\ud574 \ubcc4\ub3c4 \uc0dd\uc131\ud569\ub2c8\ub2e4."]}}, "teacherReviewSummary": "\uc54c\ub9bc\uc7a5 \uccb4\uc721\ub300\ud68c \uc2dc\ub098\ub9ac\uc624\uc5d0\uc11c \u2018\uc5b8\uc81c, \ubb34\uc5c7\uc744, \uc5b4\ub5bb\uac8c\u2019 \ud575\uc2ec \ub2e8\uc11c\ub97c \uba3c\uc800 \ucc3e\uace0 \uc900\ube44\ubb3c\uc744 2~3\ub2e8\uacc4\ub85c \uc815\ub9ac\ud558\ub294 \ud750\ub984\uc744 \uad6c\uc131\ud588\uc2b5\ub2c8\ub2e4. 2\ub2e8\uacc4\ub294 \uc138 \ubb38\uc7a5 \uc21c\uc11c \ubc30\uc5f4\ub85c \uccab \uc131\uacf5\uc744 \uc8fc\uace0, 3\ub2e8\uacc4\ub294 \uc54c\ub9bc\uc7a5 \ubb38\uc7a5\uc758 \ube48\uce78\uc5d0 \ud575\uc2ec \ub9d0\uc744 \ucc44\uc6b0\uac8c \ud558\uba70, 4\ub2e8\uacc4\uc5d0\uc11c \uce5c\uad6c\uc5d0\uac8c \ub9d0\ub85c \uc124\uba85\ud558\ub3c4\ub85d \uc804\uc774\uc2dc\ucf30\uc2b5\ub2c8\ub2e4.", "approvedByUserId": null, "approvedAt": null, "publishedAt": null}','gpt-5.1','succeeded','{"input_tokens": 90344, "input_tokens_details": {"cached_tokens": 7552}, "output_tokens": 8147, "output_tokens_details": {"reasoning_tokens": 0}, "total_tokens": 98491}',NULL,NULL,0,'2026-05-12T11:11:15.196187+00:00','2026-05-12T11:12:39.341466+00:00');
INSERT INTO agent_runs VALUES('agent_run_ca65d39a-10dd-4988-b77c-8c02e77892f0','orchestrator','orchestrator_plan_v1','OrchestratorPlanV1','{"teacherId": "user_teacher_demo", "studentId": "student_\uae40\uc9c4\uc218_daa552f0", "caseId": "case_student_\uae40\uc9c4\uc218_daa552f0", "requestedGoal": "[AI \ucd94\ucc9c \uc0dd\uc131]\n\uc120\uc0dd\ub2d8 \ucd94\uac00 \uc785\ub825 \uc5c6\uc774 \ud559\uc0dd \uae30\uc5b5\uc7a5\uce58\uc758 \uc9c0\uc6d0 \ubc29\uc2dd\ub9cc \ucc38\uace0\ud574 \uc624\ub298 \uc0ac\uc6a9\ud560 \uc0c8 \uc218\uc5c5 \uc8fc\uc81c\uc640 \ud65c\ub3d9\uc744 \ucd94\ucc9c \uc0dd\uc131\ud569\ub2c8\ub2e4.\n\uae30\uc5b5\uc7a5\uce58\uc5d0 \ub0a8\uc740 \uacfc\uac70 \uc0c1\ud669\uc740 \uc608\uc2dc \uc18c\uc7ac\uc77c \ubfd0\uc774\uba70, \uc0c8 \uc218\uc5c5 \uc8fc\uc81c\ub97c \ub36e\uc5b4\uc4f0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\uc218\uc5c5 \uc801\uc6a9 \ud78c\ud2b8\ub294 \ubb38\uc81c \uc218\uc900\uc744 \ub0ae\ucd94\ub294 \uc9c0\uc2dc\uac00 \uc544\ub2c8\ub77c \ud654\uba74 \uc81c\uc2dc \ubc29\uc2dd\uc785\ub2c8\ub2e4.\n\uc81c\uc2dc \ubc29\uc2dd \uc870\uc815: \uc120\ud0dd\uc9c0\ub97c \uc904\uc784\n\ubc18\ubcf5\ud558\uc9c0 \uc54a\uc744 \uacfc\uac70 \uc608\uc2dc \uc18c\uc7ac: \ud575\uc2ec \ub2e8\uc11c\ub97c \uba3c\uc800 \ud655\uc778\ud558\uace0, \uc9e7\uc740 \ub2e8\uacc4\ub85c \uac1c\ub150\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.", "contentType": "learning_focus", "templateRandomization": {"mode": "random_per_generation", "randomId": "19bc782b087c48fb9e339f14eaba6da1", "policy": "2~3\ub2e8\uacc4 \ud15c\ud50c\ub9bf\uc740 \ub9e4 \uc0dd\uc131\ub9c8\ub2e4 \ud6c4\ubcf4 \uc911 \ub79c\ub364\uc73c\ub85c \uc815\ud558\uace0 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 \uadf8\ub300\ub85c \uc0ac\uc6a9\ud569\ub2c8\ub2e4.", "candidateTemplates": {"2": ["blank_fill", "card_match", "clue_question", "partition_picker", "scene_question", "sequence_ordering"], "3": ["applied_question", "blank_fill", "card_match", "explanation_choice", "mini_simulation", "sequence_ordering", "wrong_explanati