ices": [{"id": "a", "text": "\uc218\uc694\uc77c"}, {"id": "b", "text": "\ubaa9\uc694\uc77c"}], "answer": "a", "correctFeedback": "\uadf8\ub798\uc694. \uc218\uc694\uc77c \ub9c9\ub300\uac00 \uac00\uc7a5 \ub192\uc544\uc11c \uc218\uc694\uc77c\uc5d0 \ube44\uac00 \uac00\uc7a5 \ub9ce\uc774 \uc654\ub2e4\uace0 \ud560 \uc218 \uc788\uc5b4\uc694.", "wrongFeedback": "\uc120\ud0dd\ud55c \uc694\uc77c \ub9c9\ub300\uc640 \uc218\uc694\uc77c \ub9c9\ub300\ub97c \ub2e4\uc2dc \ud55c\ubc88 \ub192\uc774\ub9cc \ube44\uad50\ud574 \ubcf4\uc138\uc694. \ub354 \ub192\uc740 \ub9c9\ub300\ub97c \uace0\ub974\uba74 \uc88b\uc544\uc694.", "sourceTextLines": [], "sceneTextLines": []}, "realtimeSpec": null, "imageAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_2", "audioAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_2_audio", "visualSpec": {"unitId": "visual_stage_2", "assetRole": "stage_2", "step": 2, "visualPurpose": "\ud559\uc0dd\uc774 \uac00\uc7a5 \ub192\uc740 \ub9c9\ub300\ub97c \uc27d\uac8c \ucc3e\uc744 \uc218 \uc788\ub3c4\ub85d \uadf8\ub798\ud504\ub97c \ub610\ub837\ud558\uac8c \ubcf4\uc5ec\uc900\ub2e4.", "sceneSummary": "\uac19\uc740 \ub9c9\ub300\uadf8\ub798\ud504\ub97c \uc870\uae08 \ub354 \ud655\ub300\ud558\uc5ec \ub9c9\ub300 \ub192\uc774 \ucc28\uc774\uac00 \uc798 \ubcf4\uc774\ub3c4\ub85d \ud55c \uc7a5\uba74", "primaryEvidenceObject": "\uac00\uc7a5 \ub192\uc740 \ub9c9\ub300 \ud558\ub098\uc640 \ub098\uba38\uc9c0 \ub9c9\ub300\ub4e4", "evidenceLocation": "\ud654\uba74 \uc911\uc559 \uc544\ub798\ucabd", "mustShow": ["\uc6d4~\uae08 \ub2e4\uc12f \uac1c \ub9c9\ub300\uc758 \ub192\uc774 \ucc28\uc774", "\uac00\uc7a5 \ub192\uc740 \ub9c9\ub300 \ud558\ub098", "\uc694\uc77c \uc774\ub984 \ub77c\ubca8", "\uac04\ub2e8\ud55c \ud68c\uc0c9 \ub208\uae08\uc120"], "allowedSceneText": ["\uc6d4", "\ud654", "\uc218", "\ubaa9", "\uae08"], "doNotRenderText": ["problem", "choices", "answer", "feedback", "\uc815\ub2f5 \uac15\uc870 \ud45c\uc2dc", "\ub3d9\uadf8\ub77c\ubbf8\ub098 \uccb4\ud06c \ud45c\uc2dc"], "composition": "\uadf8\ub798\ud504\uc758 \uac00\ub85c\ucd95\uacfc \ub9c9\ub300 \ubd80\ubd84\uc774 \ud654\uba74 \uac00\uc6b4\ub370 \ud06c\uac8c \ubcf4\uc774\ub3c4\ub85d \ud558\uace0, \uc138\ub85c\ucd95 \uc22b\uc790\ub294 \uc0dd\ub7b5\ud558\uac70\ub098 \ub9e4\uc6b0 \uac04\ub2e8\ud788 \ud45c\ud604\ud55c\ub2e4."}}, {"unitId": "stage_3", "step": 3, "stageId": "stage_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_3", "stageRole": "applied_problem", "templateType": "blank_fill", "studentTitle": "\ubb38\uc81c 2", "studentInstruction": "\uadf8\ub798\ud504\uc5d0\uc11c \uac00\uc7a5 \ub192\uc740 \ub9c9\ub300\ub97c \ub2e4\uc2dc \ubcf4\uace0, \uadf8 \uc694\uc77c \uc774\ub984\uc744 \ube48\uce78\uc5d0 \uc9e7\uac8c \uc801\uc5b4 \ubcf4\uc138\uc694.", "templateJson": {"imageAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_3", "audioAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_3_audio", "assetBundle": {"imageAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_3", "audioAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_3_audio"}, "question": "\uc774\ubc88 \uc8fc \ube44 \uc628 \ub0a0 \uadf8\ub798\ud504\uc5d0\uc11c \ube44\uac00 \uac00\uc7a5 \ub9ce\uc774 \uc628 \ub0a0\uc740 __ \uc785\ub2c8\ub2e4.", "sentence": "\uc774\ubc88 \uc8fc \ube44 \uc628 \ub0a0 \uadf8\ub798\ud504\uc5d0\uc11c \ube44\uac00 \uac00\uc7a5 \ub9ce\uc774 \uc628 \ub0a0\uc740 __ \uc785\ub2c8\ub2e4.", "tiles": ["\uc6d4\uc694\uc77c", "\uc218\uc694\uc77c", "\uae08\uc694\uc77c"], "acceptedAnswers": [{"answer": "\uc218\uc694\uc77c"}, {"answer": "\uc218\uc694\uc77c"}], "correctFeedback": "\uc88b\uc544\uc694. \uadf8\ub798\ud504\uc5d0\uc11c \uac00\uc7a5 \ub192\uc740 \ub9c9\ub300\ub97c \ubcf4\uace0 \u2018\uc218\uc694\uc77c\u2019\uc774\ub77c\uace0 \uc4f8 \uc218 \uc788\uc5c8\uc5b4\uc694.", "wrongFeedback": "\uadf8\ub798\ud504\uc5d0\uc11c \uac00\uc7a5 \ub192\uc740 \ub9c9\ub300\uac00 \uc788\ub294 \uc694\uc77c \uc774\ub984\uc744 \ub2e4\uc2dc \ubcf4\uace0, \uadf8 \uc774\ub984\uc744 \ube48\uce78\uc5d0 \uadf8\ub300\ub85c \uc801\uc5b4 \ubcf4\uc138\uc694.", "sourceTextLines": [], "sceneTextLines": []}, "realtimeSpec": null, "imageAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_3", "audioAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_3_audio", "visualSpec": {"unitId": "visual_stage_3", "assetRole": "stage_3", "step": 3, "visualPurpose": "\ud559\uc0dd\uc774 \uae30\uc5b5\uc744 \ubc14\ud0d5\uc73c\ub85c \ube48\uce78\uc5d0 \uc694\uc77c\uc744 \ucc44\uc6b0\ub294 \ud65c\ub3d9\uc744 \ud560 \uadf8\ub798\ud504\ub97c \ubcf4\uc5ec\uc900\ub2e4.", "sceneSummary": "\ube44\uc2b7\ud55c \uad6c\uc870\uc758 \ub9c9\ub300\uadf8\ub798\ud504\uc5d0\uc11c \uac00\uc7a5 \ub192\uc740 \ub9c9\ub300 \uc704\ucabd\uc5d0 \uc791\uc740 \ube48 \ub9d0\ud48d\uc120\uc774\ub098 \ube48 \ub77c\ubca8 \uacf5\uac04\uc774 \uc788\ub294 \uc7a5\uba74", "primaryEvidenceObject": "\uac00\uc7a5 \ub192\uc740 \ub9c9\ub300\uc640 \uadf8 \uc704\uc758 \ube48 \ub77c\ubca8 \uacf5\uac04", "evidenceLocation": "\uadf8\ub798\ud504 \uc0c1\ub2e8 \uc911\uc559", "mustShow": ["\uc6d4~\uae08 \uc694\uc77c \ub9c9\ub300 \uadf8\ub798\ud504", "\ud55c \ub9c9\ub300\uac00 \ub2e4\ub978 \ub9c9\ub300\ubcf4\ub2e4 \ud655\uc2e4\ud788 \ub192\uc74c", "\uac00\uc7a5 \ub192\uc740 \ub9c9\ub300 \uc704\uc5d0 \ube44\uc5b4 \uc788\ub294 \uc791\uc740 \ub77c\ubca8 \uacf5\uac04(\uae00\uc790 \uc5c6\uc74c)"], "allowedSceneText": ["\uc774\ubc88 \uc8fc \ube44 \uc628 \ub0a0", "\uc6d4", "\ud654", "\uc218", "\ubaa9", "\uae08"], "doNotRenderText": ["problem", "choices", "answer", "feedback", "\ud559\uc0dd\uc774 \ucc44\uc6b8 \ub2f5\uc548 \uae00\uc790", "\ud78c\ud2b8 \ubb38\uc7a5"], "composition": "\uadf8\ub798\ud504 \uc804\uccb4\ub97c \ubcf4\uc774\ub418, \uac00\uc7a5 \ub192\uc740 \ub9c9\ub300\uc640 \uadf8 \uc704\uc758 \ube48 \ub77c\ubca8 \uacf5\uac04\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc2dc\uc120\uc774 \uac00\ub3c4\ub85d \uc57d\uac04 \uc0c1\ub2e8 \uc911\uc2ec\uc5d0 \ub450\uace0 \uc5ec\ubc31\uc744 \ub454\ub2e4."}}, {"unitId": "stage_4", "step": 4, "stageId": "stage_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_4", "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "studentInstruction": "\uc0c8 \uadf8\ub798\ud504\ub97c \ub5a0\uc62c\ub9ac\uba70, \uba3c\uc800 \uc5b4\ub514\ub97c \ubcf4\uace0 \uc65c \uadf8 \ubd80\ubd84\uc774 \uc911\uc694\ud55c\uc9c0 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc124\uba85\ud574 \ubcf4\uc138\uc694.", "templateJson": {"imageAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_4_realtime", "audioAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_4_realtime", "audioAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_4_realtime_audio"}, "situationText": "\uc774\ubc88\uc5d0\ub294 \ud558\ub8e8 \uc911 \uc544\uce68, \uc810\uc2ec, \uc800\ub141\uc5d0 \ube44\uac00 \uc5b4\ub290 \ub54c \uac00\uc7a5 \ub9ce\uc774 \uc654\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc0c8\ub85c\uc6b4 \ub9c9\ub300\uadf8\ub798\ud504\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4. \uc5b4\ub5a4 \ubd80\ubd84\uc744 \uba3c\uc800 \ubcf4\uace0 \uc774\uc720\ub97c \ub9d0\ud574 \ubcfc\uae4c\uc694?", "practicePrompt": "\uadf8\ub798\ud504\ub97c \ucc98\uc74c \ubcfc \ub54c, \ub098\ub294 \uba3c\uc800 __________ \ubd80\ubd84\uc744 \ubcf4\uace0, \uadf8 \uc774\uc720\ub294 __________ \ub77c\uace0 \ub9d0\ud574 \ubcf4\uc138\uc694.", "sourceTextLines": [], "sceneTextLines": []}, "realtimeSpec": {"id": "rt_spec_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1", "stageId": "stage_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ud55c \ubc88 \ud574\ubcf4\uae30", "situationText": "\uc544\uce68, \uc810\uc2ec, \uc800\ub141\uc5d0 \ube44\uac00 \uc628 \uc591\uc744 \ub9c9\ub300\uadf8\ub798\ud504\ub85c \ubcf4\uc5ec \uc8fc\ub294 \uac8c\uc2dc\ud310\uc744 \ubcf4\uace0 \uc788\ub2e4\uace0 \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4. \uc774 \uadf8\ub798\ud504\ub97c \ucc98\uc74c \ubcfc \ub54c \uc5b4\ub514\ub97c \uba3c\uc800 \ubcf4\uace0, \uc65c \uadf8 \ubd80\ubd84\uc774 \uc911\uc694\ud55c\uc9c0 \ub9d0\ub85c \uc124\uba85\ud574 \ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud569\ub2c8\ub2e4.", "aiRole": "\uce5c\uc808\ud55c \uacfc\ud559 \uc120\uc0dd\ub2d8", "openingLine": "\uc9c0\uae08 \ub208\uc55e\uc5d0 \uc544\uce68, \uc810\uc2ec, \uc800\ub141 \ub9c9\ub300\uac00 \uc788\ub294 \ube44 \uadf8\ub798\ud504\uac00 \uc788\ub2e4\uace0 \uc0c1\uc0c1\ud574 \ubcfc\uac8c\uc694. \uba3c\uc800 \uc5b4\ub514\ub97c \ubcf4\uace0 \uc2f6\ub098\uc694? \uadf8\ub9ac\uace0 \uc65c \uadf8 \ubd80\ubd84\uc774 \uc911\uc694\ud55c\uc9c0 \ucc28\uadfc\ucc28\uadfc \ub9d0\ud574 \uc8fc\uc138\uc694.", "studentGoal": "\uc0c8\ub85c\uc6b4 \ub9c9\ub300\uadf8\ub798\ud504\ub97c \ub5a0\uc62c\ub9ac\uba70 \u2018\uac00\uc7a5 \ub192\uc740 \ub9c9\ub300\u2019\ucc98\ub7fc \ud575\uc2ec \ub2e8\uc11c\ub97c \uba3c\uc800 \uc5b4\ub514\uc11c \ucc3e\uc744\uc9c0 \ub9d0\ud558\uace0, \uadf8 \uc774\uc720\ub97c \ud55c \ubb38\uc7a5\uc73c\ub85c \uc124\uba85\ud574 \ubcf8\ub2e4.", "rubric": [{"id": "r1", "label": "\uadf8\ub798\ud504\uc5d0\uc11c \uba3c\uc800 \ubcfc \ubd80\ubd84\uc744 \ud55c \uacf3\uc73c\ub85c \uc815\ud574\uc11c \ub9d0\ud55c\ub2e4.", "required": true}, {"id": "r2", "label": "\uc65c \uadf8 \ubd80\ubd84\uc774 \uc911\uc694\ud55c\uc9c0 \uc774\uc720\ub97c \ud55c \ubb38\uc7a5\uc73c\ub85c \ub367\ubd99\uc778\ub2e4.", "required": true}, {"id": "r3", "label": "\u2018\uac00\uc7a5 \ub192\uc740 \ub9c9\ub300\u2019\ucc98\ub7fc \ub192\uc774 \ucc28\uc774\ub97c \ub2e8\uc11c\ub85c \uc0bc\uc73c\ub824\uace0 \uc2dc\ub3c4\ud55c\ub2e4.", "required": false}, {"id": "r4", "label": "\ub9d0\uc774 \ub9c9\ud600\ub3c4 \uc7a0\uae50 \uc0dd\uac01\ud55c \ub4a4 \ub2e4\uc2dc \ud55c \ubc88 \uc2dc\ub3c4\ud574 \ubcf8\ub2e4.", "required": false}], "allowedFeedback": ["\ud559\uc0dd\uc774 \uba3c\uc800 \uc5b4\ub514\ub97c \ubcf4\uaca0\ub2e4\uace0 \ub9d0\ud558\uba74 \uadf8 \uc120\ud0dd\uc744 \uc778\uc815\ud574 \uc8fc\uace0, \uc65c \uc911\uc694\ud55c\uc9c0 \ud55c \uac00\uc9c0 \uc774\uc720\ub97c \ub354 \ub9d0\ud574 \ubcf4\ub3c4\ub85d \ubd80\ub4dc\ub7fd\uac8c \uc9c8\ubb38\ud569\ub2c8\ub2e4.", "\ud559\uc0dd\uc774 \uc774\uc720\ub97c \ub9d0\ud558\uae30 \uc5b4\ub824\uc6cc\ud558\uba74 \uadf8\ub798\ud504\uc758 \ub192\uc774 \ucc28\uc774\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc9e7\uc740 \ud78c\ud2b8\ub97c \uc8fc\uace0, \uc2a4\uc2a4\ub85c \ubb38\uc7a5\uc744 \uc644\uc131\ud558\uac8c \ub3c4\uc640\uc90d\ub2c8\ub2e4.", "\ud559\uc0dd\uc774 \ub2e4\ub978 \ud45c\ud604\uc744 \uc368\ub3c4 \uc758\ubbf8\uac00 \ud1b5\ud558\uba74 \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc774\uace0, \ud544\uc694\ud55c \uacbd\uc6b0 \ub354 \uc27d\uac8c \ub9d0\ub85c \uc815\ub9ac\ud574 \uc90d\ub2c8\ub2e4."], "forbidden": ["\uc815\ub2f5 \ubb38\uc7a5\uc744 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \ub300\uc2e0 \ub9d0\ud558\uc9c0 \uc54a\uae30", "\ud559\uc0dd\uc774 \ud55c \ubc88 \ud2c0\ub9ac\uac70\ub098 \ub9c9\ud78c \ub4a4 \ubc14\ub85c \uc7ac\ucd09\ud558\uc9c0 \uc54a\uae30", "\ube44\uad50\ub098 \ud3c9\uac00\ud558\ub294 \ub9d0\ud22c\ub85c \ud559\uc0dd\uc758 \uc124\uba85\uc744 \ube44\ud310\ud558\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 180, "postPracticeReflection": ["\uadf8\ub798\ud504\ub97c \ubcfc \ub54c \ub098\ub294 \uc5b4\ub514\ubd80\ud130 \ubcf4\ub294 \uac83\uc774 \ud3b8\ud588\ub294\uc9c0 \ub9d0\ub85c \uc815\ub9ac\ud574 \ubcfc\uae4c\uc694?", "\uc624\ub298 \ub