INSERT INTO support_cases VALUES('case_student_김진수_daa552f0','student_김진수_daa552f0','user_teacher_demo','open','핵심 단서를 먼저 확인하고, 짧은 단계로 개념을 설명합니다.','2026-05-12T11:12:05.505994+00:00','learning','관찰상 효과가 확인된 지원은 선택지를 줄임입니다. 수업에서는 선택지 수 줄이기, 생각할 시간이 있을 때 안정됨을 적용합니다. 문제에서 핵심 단서 찾기 부담을 먼저 낮춥니다.');
INSERT INTO support_cases VALUES('case_student_최하늘_676c91bc','student_최하늘_676c91bc','user_teacher_demo','open','핵심 단서를 먼저 확인하고, 짧은 단계로 개념을 설명합니다.','2026-05-12T07:55:43.165648+00:00','feedback','관찰상 효과가 확인된 지원은 예시 문제를 먼저 보여줌입니다. 수업에서는 예시 문제를 먼저 보여주기, 쉬운 첫 문항이 있을 때 안정됨을 적용합니다. 긴 문제 조건 이해 부담을 먼저 낮춥니다.');
INSERT INTO memory_cards VALUES('memory_student_김진수_daa552f0','student_김진수_daa552f0','case_student_김진수_daa552f0',1,'["\ud575\uc2ec \ub2e8\uc11c\ub97c \uba3c\uc800 \ud655\uc778\ud558\uace0, \uc9e7\uc740 \ub2e8\uacc4\ub85c \uac1c\ub150\uc744 \uc124\uba85\ud569\ub2c8\ub2e4."]','{"registrationObservation": "\uc9c0\ub8e8\ud55c \uae00\uc774\ub098 \ud14d\uc2a4\ud2b8 \ud615\uc2dd\uc758 \uad50\uc721\uc790\ub8cc\ub294 \ube44\uc120\ud638\ud558\uace0 \uadf8\ub9bc\uc774\ub098 \uc0ac\uc9c4 \ub4f1\uc744 \uc880 \ub354 \uc120\ud638\ud568", "strengths": ["\uadf8\ub9bc\u00b7\ud45c\u00b7\uc790\ub8cc \ub2e8\uc11c\ub97c \uba3c\uc800 \ucc3e\uc74c\uc5d0\uc11c \uac15\uc810\uc774 \uad00\ucc30\ub429\ub2c8\ub2e4.", "\ud55c \ubb38\ud56d\uc529 \ub05d\uae4c\uc9c0 \ud482\uc5d0\uc11c \uac15\uc810\uc774 \uad00\ucc30\ub429\ub2c8\ub2e4."], "weaknesses": ["\ubb38\uc81c\uc5d0\uc11c \ud575\uc2ec \ub2e8\uc11c \ucc3e\uae30 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."], "preferredSupports": ["\uc120\ud0dd\uc9c0\ub97c \uc904\uc784"], "supportIntake": {"sourceBasis": ["\uae30\ucd08\ud559\ub825 \uc9c0\uc6d0 \uad00\ucc30 \uad00\uc810", "\ud559\uc2b5 \uacfc\uc81c \ubc18\uc751 \uad00\uc810", "\ubb38\uc81c \uc870\uac74\u00b7\uc77d\uae30 \ubd80\ub2f4 \uc870\uc815 \uad00\uc810"], "learningResponse": {"observedStrengths": ["\uadf8\ub9bc\u00b7\ud45c\u00b7\uc790\ub8cc \ub2e8\uc11c\ub97c \uba3c\uc800 \ucc3e\uc74c", "\ud55c \ubb38\ud56d\uc529 \ub05d\uae4c\uc9c0 \ud482"], "effectiveSupports": ["\uc120\ud0dd\uc9c0\ub97c \uc904\uc784"], "readingLoad": "medium", "instructionBurdens": [], "communicationNeeds": ["\uc815\ub2f5 \uc774\uc720 \uc9e7\uac8c \ub9d0\ud558\uae30"], "choiceCountLimit": 2}, "challengeBehaviorPriorities": [{"label": "\ubb38\uc81c\uc5d0\uc11c \ud575\uc2ec \ub2e8\uc11c \ucc3e\uae30", "priority": 1}], "behaviorFunctionHypotheses": [], "replacementSkills": ["\uc815\ub2f5 \uc774\uc720 \uc9e7\uac8c \ub9d0\ud558\uae30"], "recommendedScaffolds": ["\uc120\ud0dd\uc9c0\u