INSERT INTO memory_cards VALUES('memory_student_최하늘_676c91bc','student_최하늘_676c91bc','case_student_최하늘_676c91bc',1,'["\ud575\uc2ec \ub2e8\uc11c\ub97c \uba3c\uc800 \ud655\uc778\ud558\uace0, \uc9e7\uc740 \ub2e8\uacc4\ub85c \uac1c\ub150\uc744 \uc124\uba85\ud569\ub2c8\ub2e4."]','{"registrationObservation": "\uae34 \uc870\uac74\uc744 \ud55c\ubc88\uc5d0 \uc77d\uc73c\uba74 \ud575\uc2ec \ub2e8\uc5b4\ub97c \ub193\uce60\uc218\uc788\uc74c", "strengths": ["\uc9e7\uc740 \uc608\uc2dc\ub97c \ubcf4\uace0 \uc774\ud574\ud569\ub2c8\ub2e4."], "weaknesses": ["\uae34 \ubb38\uc81c \uc870\uac74 \uc774\ud574 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."], "preferredSupports": ["\uc608\uc2dc \ubb38\uc81c\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c"], "supportIntake": {"sourceBasis": ["\uae30\ucd08\ud559\ub825 \uc9c0\uc6d0 \uad00\ucc30 \uad00\uc810", "\ud559\uc2b5 \uacfc\uc81c \ubc18\uc751 \uad00\uc810", "\ubb38\uc81c \uc870\uac74\u00b7\uc77d\uae30 \ubd80\ub2f4 \uc870\uc815 \uad00\uc810"], "learningResponse": {"observedStrengths": ["\uc9e7\uc740 \uc608\uc2dc\ub97c \ubcf4\uace0 \uc774\ud574\ud568"], "effectiveSupports": ["\uc608\uc2dc \ubb38\uc81c\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c"], "readingLoad": "medium", "instructionBurdens": [], "communicationNeeds": ["\ub2e4\uc2dc \uc124\uba85\ud574\ub2ec\ub77c\uace0 \uc694\uccad"], "choiceCountLimit": 3}, "challengeBehaviorPriorities": [{"label": "\uae34 \ubb38\uc81c \uc870\uac74 \uc774\ud574", "priority": 1}], "behaviorFunctionHypotheses": [], "replacementSkills": ["\ub2e4\uc2dc \uc124\uba85\ud574\ub2ec\ub77c\uace0 \uc694\uccad"], "recommendedScaffolds": ["\uc608\uc2dc \ubb38\uc81c\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\uc26c\uc6b4 \uccab \ubb38\ud56d\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428"], "avoidGuidance": ["\uae34 \ubb38\uc81c \uc870\uac74 \uc774\ud574", "\uae34 \uc124\uba85\ubd80\ud130 \uc2dc\uc791"], "teacherObservation": "\uae34 \uc870\uac74\uc744 \ud55c\ubc88\uc5d0 \uc77d\uc73c\uba74 \ud575\uc2ec \ub2e8\uc5b4\ub97c \ub193\uce60\uc218\uc788\uc74c", "guardianShareNote": null, "checklistSummary": {"observedStrengths": ["\uc9e7\uc740 \uc608\uc2dc\ub97c \ubcf4\uace0 \uc774\ud574\ud568"], "hardSituations": ["\uae34 \ubb38\uc81c \uc870\uac74 \uc774\ud574"], "effectiveSupports": ["\uc608\uc2dc \ubb38\uc81c\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c"], "instructionBurdens": [], "communicationNeeds": ["\ub2e4\uc2dc \uc124\uba85\ud574\ub2ec\ub77c\uace0 \uc694\uccad"], "calmingSupports": ["\uc26c\uc6b4 \uccab \ubb38\ud56d\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428"], "avoidGuidance": ["\uae34 \uc124\uba85\ubd80\ud130 \uc2dc\uc791"]}}, "latestTeacherReportId": "teacher_report_81d8c83b-c19c-417e-809b-6522223ef4a0", "latestTeacherReportSummary": "## \uc218\uc5c5 \ubc18\uc751\n\n> \uc9e7\uc740 \uc548\ub0b4\uc640 \uc608\uc2dc \ud6c4 \ub05d\uae4c\uc9c0 \ucc38\uc5ec\ud588\uace0, \uaddc\uce59 \ub098\ub204\uae30 \uc790\uccb4\ub294 \u2018\uc7ac\ubbf8\uc788\ub2e4\u2019\uace0 \ud68c\uace0\ud588\uc2b5\ub2c8\ub2e4.\n\n- \uc218\ud589 \uc218\uce58: \uc644\ub8cc\uc728 100%, \uc815\ub2f5\ub960 67%\ub85c 4\ub2e8\uacc4 \ud65c\ub3d9\uc744 \ubaa8\ub450 \ub9c8\ubb34\ub9ac\ud588\uc2b5\ub2c8\ub2e4.  \n- \uc815\uc11c \ubc18\uc751: \ud559\uc0dd \ud68c\uace0\uc5d0\uc11c \u201c\uc7ac\ubbf8\uc368\uc694\u201d\ub77c\uace0 \uc751\ub2f5\ud574 \uaddc\uce59 \uc124\uba85 \ud65c\ub3d9\uc5d0 \ub300\ud55c \uae0d\uc815 \ubc18\uc751\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.  \n- \ubc1c\ud654/\ud589\ub3d9 \uae30\ub85d: \uc2e4\uc2dc\uac04 \ub9d0\ud558\uae30 \ub2e8\uacc4\uc5d0\uc11c \ud559\uc0dd \ubc1c\ud654\uac00 \ubd84\ub9ac \uae30\ub85d\ub418\uc9c0 \uc54a\uc544, \uc2e4\uc81c \uc124\uba85 \ub9d0\ud558\uae30 \ud589\ub3d9\uc740 \ucd94\uac00 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.  \n\n## \uc774\ud574 \ubcc0\ud654\n\n> \uc608\uc2dc\uc640 \ub2e8\uc11c \ud45c\uc2dc \ud6c4 \uc120\ud0dd \ud65c\ub3d9\uc740 \uc218\ud589\ud588\uc73c\ub098, \uaddc\uce59\uc744 2~3\ub2e8\uacc4\ub85c \uc815\ud655\ud788 \ub098\ub204\ub294 \uc774\ud574\ub294 \uc544\uc9c1 \uc77c\ubd80\ub9cc \ud655\uc778\ub429\ub2c8\ub2e4.\n\n- \uc548\uc815 \uc870\uac74: \uc608\uc2dc \ubb38\uc81c\u00b7\uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \uc81c\uc2dc\ud558\uace0, \uc870\uac74\uc744 \uc9e7\uac8c \ub04a\uc5b4 \uc77d\uc744 \ub54c \ubb38\ud56d \uc218\ud589\uc774 \uac00\ub2a5\ud588\ub358 \uac83\uc73c\ub85c \ud655\uc778\ub429\ub2c8\ub2e4.  \n- \uc804\uc774 \uc870\uac74: \ud575\uc2ec \ub2e8\uc11c\ub97c \ubc14\ud0d5\uc73c\ub85c \ud55c \ubb38\uc7a5 \uc120\ud0dd \ud65c\ub3d9\uc5d0\uc11c\ub294 \uc77c\ubd80 \uc624\ub2f5\uc774 \uc788\uc5b4, \ub2e8\uc11c \uc774\ud574\uac00 \uc124\uba85 \ub2e8\uacc4\ub85c \uc644\uc804\ud788 \uc804\uc774\ub418\uc5c8\ub294\uc9c0\ub294 \ubd88\ud655\uc2e4\ud569\ub2c8\ub2e4.  \n- \ud655\uc778 \ud544\uc694: \uae34 \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \uc77d\uc744 \ub54c ", "selectedMemoryCandidates": ["\ub9d0\ud558\uae30 \ub2e8\uacc4\uc5d0\uc11c\ub294 \uc2e4\uc81c \ud559\uc0dd \ubc1c\ud654\ub97c \ub2e4\uc2dc \ud655\uc778\ud558\uae30", "\uc608\uc2dc \ubb38\uc81c\u00b7\uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \uc81c\uc2dc\ud558\uae30", "\uc870\uac74 \ubb38\uc7a5\uc744 1~2\ubb38\uc7a5\uc529 \ub04a\uc5b4 \uc77d\uae30"]}','긴 조건을 한번에 읽으면 핵심 단어를 놓칠수있음','["\uc608\uc2dc \ubb38\uc81c\ub97c \uba3c\uc800 \ubcf4\uc5ec\uc90c", "\ub9d0\ud558\uae30 \ub2e8\uacc4\uc5d0\uc11c\ub294 \uc2e4\uc81c \ud559\uc0dd \ubc1c\ud654\ub97c \ub2e4\uc2dc \ud655\uc778\ud558\uae30", "\uc608\uc2dc \ubb38\uc81c\u00b7\uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \uc81c\uc2dc\ud558\uae30", "\uc870\uac74 \ubb38\uc7a5\uc744 1~2\ubb38\uc7a5\uc529 \ub04a\uc5b4 \uc77d\uae30"]','["\uae34 \ubb38\uc81c \uc870\uac74 \uc774\ud574 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."]',NULL,'["\uae34 \ubb38\uc81c \uc870\uac74 \uc774\ud574 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."]','2026-05-12T11:21:50.738166+00:00','active');
