aviorFunctionHypotheses": [], "replacementSkills": ["\uc815\ub2f5 \uc774\uc720 \uc9e7\uac8c \ub9d0\ud558\uae30"], "recommendedScaffolds": ["\uc120\ud0dd\uc9c0\ub97c \uc904\uc784", "\uc0dd\uac01\ud560 \uc2dc\uac04\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428"], "avoidGuidance": ["\ubb38\uc81c\uc5d0\uc11c \ud575\uc2ec \ub2e8\uc11c \ucc3e\uae30", "\uc624\ub2f5 \uc9c1\ud6c4 \uc7ac\ucd09"], "teacherObservation": "\uc9c0\ub8e8\ud55c \uae00\uc774\ub098 \ud14d\uc2a4\ud2b8 \ud615\uc2dd\uc758 \uad50\uc721\uc790\ub8cc\ub294 \ube44\uc120\ud638\ud558\uace0 \uadf8\ub9bc\uc774\ub098 \uc0ac\uc9c4 \ub4f1\uc744 \uc880 \ub354 \uc120\ud638\ud568", "guardianShareNote": null, "checklistSummary": {"observedStrengths": ["\uadf8\ub9bc\u00b7\ud45c\u00b7\uc790\ub8cc \ub2e8\uc11c\ub97c \uba3c\uc800 \ucc3e\uc74c", "\ud55c \ubb38\ud56d\uc529 \ub05d\uae4c\uc9c0 \ud482"], "hardSituations": ["\ubb38\uc81c\uc5d0\uc11c \ud575\uc2ec \ub2e8\uc11c \ucc3e\uae30"], "effectiveSupports": ["\uc120\ud0dd\uc9c0\ub97c \uc904\uc784"], "instructionBurdens": [], "communicationNeeds": ["\uc815\ub2f5 \uc774\uc720 \uc9e7\uac8c \ub9d0\ud558\uae30"], "calmingSupports": ["\uc0dd\uac01\ud560 \uc2dc\uac04\uc774 \uc788\uc744 \ub54c \uc548\uc815\ub428"], "avoidGuidance": ["\uc624\ub2f5 \uc9c1\ud6c4 \uc7ac\ucd09"]}}, "school": {"id": "school_7751094", "officeCode": "J10", "schoolCode": "7751094", "schoolName": "\uc194\uac1c\ucd08\ub4f1\ud559\uad50", "schoolKind": "\ucd08\ub4f1\ud559\uad50", "regionName": "\uacbd\uae30\ub3c4", "roadAddress": "\uacbd\uae30\ub3c4 \uc6a9\uc778\uc2dc \uc218\uc9c0\uad6c \uc0c1\ud604\ub85c 79", "sourceCode": "neis_open_api"}}','2026-05-12T11:12:05.506046+00:00');
INSERT INTO student_support_profiles VALUES('support_profile_draft_student_최하늘_676c91bc_2b9f7f14','student_최하늘_676c91bc','support_intake_student_최하늘_676c91bc_87c5174d','draft','{"profileVersion": "support_profile_v1", "draftLabel": "\ucd08\uc548 \uc0dd\uc131 2026-05-12", "lessonDesignHints": ["\uc218\uc5c5\uc744 \uc2dc\uc791\ud560 \ub54c\ub294 \uc544\uc8fc \uc9e7\uc740 \uc608\uc2dc \ubb38\uc81c\ub098 \uc0c1\ud669\uc744 \uba3c\uc800 \ubcf4\uc5ec\uc8fc\uace0, \uadf8 \uc548\uc5d0\uc11c \ud575\uc2ec \ub2e8\uc11c\ub97c \ud568\uaed8 \ud45c\uc2dc\ud574 \ubd05\ub2c8\ub2e4.", "\ubcf8 \ubb38\uc81c\ub294 \uc870\uac74\uc744 \ub450\uc138 \uc904 \ub2e8\uc704\ub85c \ub098\ub204\uc5b4 \uc81c\uc2dc\ud558\uace0, \uac01 \ub2e8\ub77d\uc5d0\uc11c \uaf2d \ubd10\uc57c \ud560 \ub2e8\uc5b4\ub97c \uad75\uac8c \ud45c\uc2dc\ud558\uac70\ub098 \ubc11\uc904\ub85c \uad6c\ubd84\ud574 \uc90d\ub2c8\ub2e4.", "\uc0c8 \uac1c\ub150 \uc124\uba85\uc740 2~3\ub2e8\uacc4 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub04a\uc5b4\uc11c \uc81c\uc2dc\ud558\uace0, \ub2e8\uacc4\ub9c8\ub2e4 \uc608\uc2dc\uc640 \uc5f0\uacb0\ud574 \ud655\uc778 \uc9c8\ubb38\uc744 \ud55c \ubc88\uc529 \ub123\uc5b4 \uc90d\ub2c8\ub2e4.", "\uae34 \uc124\uba85\uc744 \ud55c \ubc88\uc5d0 \uc77d\ud788\uae30\ubcf4\ub2e4, \ud559\uc0dd\uc774 \u2018\ub2e4\uc2dc \uc124\uba85\ud574 \uc8fc\uc138\uc694\u2019\ub77c\uace0 \ub9d0\ud560 \uc218 \uc788\ub294 \uae30\ud68c\ub97c \uc790\uc8fc \uc8fc\uace0 \uadf8\ub54c\ub9c8\ub2e4 \ud575\uc2ec\ub9cc \uace8\ub77c \uc7ac\uc124\uba85\ud569\ub2c8\ub2e4."], "learningResponsePattern": {"worksWell": ["\uc9e7\uc740 \uc608\uc2dc\ub098 \uac04\ub2e8\ud55c \ubb38\uc81c\ub97c \ubcf4\uace0 \uac1c\ub150\uc744 \uc774\ud574\ud558\ub294 \ud3b8\uc785\ub2c8\ub2e4.", "\uc26c\uc6b4 \uccab \ubb38\ud56d\uc774 \ub098\uc62c \ub54c \uc548\uc815\uc801\uc73c\ub85c \uc2dc\uc791\ud558\ub294 \ubaa8\uc2b5\uc774 \uad00\ucc30\ub429\ub2c8\ub2e4.", "\uc608\uc2dc\ub97c \uba3c\uc800 \ubcf8 \ub4a4 \ube44\uc2b7\ud55c \uc720\ud615\uc758 \ubb38\uc81c\ub85c \uc774\uc5b4\uc9c8 \ub54c \ubc18\uc751\uc774 \ubd80\ub4dc\ub7fd\uc2b5\ub2c8\ub2e4."], "canBeHard": ["\uae34 \ubb38\uc81c \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \uc77d\uc744 \ub54c \ud575\uc2ec \ub2e8\uc5b4\ub97c \ub193\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4.", "\uae34 \uc124\uba85\uc73c\ub85c \uc218\uc5c5\uc744 \uc2dc\uc791\ud558\uba74 \ub0b4\uc6a9 \ud30c\uc545\uc5d0 \ubd80\ub2f4\uc744 \ub290\ub084 \uc218 \uc788\uc2b5\ub2c8\ub2e4.", "\uc870\uac74 \ubb38\uc7a5 \uc18d\uc5d0\uc11c \uc5b4\ub5a4 \uc815\ubcf4\uac00 \uc911\uc694\ud55c\uc9c0 \uc2a4\uc2a4\ub85c \uace0\ub974\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4."], "choiceCountLimit": 3, "readingLoad": "medium", "explanationStyle": "\uc608\uc2dc \u2192 \uc9e7\uc740 \uc124\uba85 \u2192 \ud575\uc2ec \ub2e8\uc11c \ud45c\uc2dc \u2192 \ube44\uc2b7\ud55c \ubb38\uc81c\ub85c \ud55c \ub2e8\uacc4\uc529 \ud655\uc7a5\ud558\ub294 \ubc29\uc2dd\uc774 \uc798 \ub9de\uc2b5\ub2c8\ub2e4."}, "behaviorSupportProfile": {"priorityBehaviors": ["\uae34 \uc870\uac74\uc774 \uc788\ub294 \ud559\uc2b5 \uacfc\uc81c\uc5d0\uc11c \ud575\uc2ec \ub2e8\uc11c\ub97c \ub193\uce58\uc9c0 \uc54a\uace0 \ucc3e\uae30"], "functionHypotheses": ["\uae34 \uae00\uc774\ub098 \uc870\uac74\uc774 \ud55c \ubc88\uc5d0 \uc81c\uc2dc\ub418\uba74 \uc815\ubcf4\ub7c9\uc774 \ub9ce\uc544\uc838 \uacfc\uc81c \uc774\ud574\uc5d0 \uc5b4\ub824\uc6c0\uc774 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4."], "replacementSkills": ["\ubb38\uc81c\ub97c \uc77d\ub2e4\uac00 \uc798 \ubaa8\ub974\uaca0\uc744 \ub54c \u2018\ub2e4\uc2dc \ud55c \ubc88 \uc9e7\uac8c \uc124\uba85\ud574 \uc8fc\uc138\uc694\u2019\ub77c\uace0 \ub9d0\ud558\uae30", "\ubb38\uc81c \uc870\uac74\uc744 \uc77d\uc73c\uba70 \uc911\uc694\ud55c \ub2e8\uc5b4\uc5d0 \ubc11\uc904\uc774\ub098 \ub3d9\uadf8\ub77c\ubbf8 \ud45c\uc2dc\ud558\uae30", "\uae34 \uc870\uac74\uc744 \uc2a4\uc2a4\ub85c \ub450\uc138 \ubd80\ubd84\uc73c\ub85c \ub098\ub204\uc5b4 \ucc28\ub840\ub85c \uc77d\uc5b4 \ubcf4\uae30", "\ubb38\uc81c\uc5d0\uc11c \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud560 \uc815\ubcf4\ub97c \uc785\uc73c\ub85c \ud55c \ubc88 \ub9d0\ud574 \ubcf4\uae30"], "recommendedScaffolds": ["\uc608\uc2dc \ubb38\uc81c\uac00 \ud3ec\ud568\ub41c \uc124\uba85 \uc608\uc2dc \uc81c\uc2dc", "\uc870\uac74\uc744 \uc9e7\uac8c \ub04a\uc5b4 \uc81c\uc2dc\ud558\ub294 \uc9e7\uc740 \ub2e8\uacc4 \ubd84\ud560", "\ud575\uc2ec \ub2e8\uc5b4\ub97c \uc2dc\uac01\uc801\uc73c\ub85c \uac15\uc870\ud55c \ubb38\ud56d \uc81c\uc2dc", "\uc26c\uc6b4 \ub09c\uc774\ub3c4\uc758 \uccab \ubb38\ud56d\uc73c\ub85c \uc2dc\uc791\ud558\uae30", "\ud480\uc774 \uc21c\uc11c\ub97c \uac04\ub2e8\ud788 \uc801\uc740 \ub2e8\uacc4 \uce74\ub4dc \uc81c\uacf5", "\ub450\uc138 \uac1c \ubcf4\uae30\ub9cc \uc81c\uc2dc\ud558\ub294 \uc120\ud0dd\uc9c0 \ucd95\uc18c"]}, "strengths": ["\uc9e7\uc740 \uc608\uc2dc\uc640 \ud568\uaed8 \uc81c\uc2dc\ud558\uba74 \uc0c8\ub85c\uc6b4 \uac1c\ub150\uc774\ub098 \ubb38\uc81c \uc0c1\ud669\uc744 \uc798 \uc774\ud574\ud569\ub2c8\ub2e4.", "\uc26c\uc6b4 \uccab \ubb38\ud56d\uc744 \ud1b5\ud574 \uc131\uacf5 \uacbd\ud5d8\uc744 \ud55c \ub4a4\uc5d0\ub294 \ub2e4\uc74c \ubb38\uc81c\ub3c4 \ube44\uad50\uc801 \uc548\uc815\uc801\uc73c\ub85c \uc2dc\ub3c4\ud569\ub2c8\ub2e4.", "\ud544\uc694\ud560 \ub54c \ub2e4\uc2dc \uc124\uba85\uc744 \uc694\uccad\ud558\ub294 \ub4f1 \ub3c4\uc6c0\uc744 \uad6c\ud558\ub824\ub294 \uc2dc\ub3c4\ub97c \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."], "supportCautions": ["\uae34 \ubb38\uc81c \uc870\uac74\uc774\ub098 \uc124\uba85\uc744 \ud55c \ubc88\uc5d0 \uc81c\uc2dc\ud558\uba74 \ud575\uc2ec \uc815\ubcf4\ub97c \ub193\uce58\uace0 \ub0b4\uc6a9 \uc774\ud574\uac00 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.", "\uc218\uc5c5\uc744 \uae34 \ub9d0 \uc124\uba85\uc73c\ub85c \uc2dc\uc791\ud558\uba74 \uc9d1\uc911\uc774 \ub5a8\uc5b4\uc9c0\uac70\ub098 \uacfc\uc81c \ucc38\uc5ec\uac00 \ub2a6\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.", "\ubb38\uc81c \uc870\uac74\uc758 \uc5b4\ub5a4 \ubd80\ubd84\uc774 \uc911\uc694\ud55c\uc9c0 \uc548\ub0b4 \uc5c6\uc774 \uc2a4\uc2a4\ub85c \uace8\ub77c\ub0b4\uae30\ub294 \uc544\uc9c1 \ubd80\ub2f4\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4."], "source": {"intakeSourceId": "support_intake_student_\ucd5c\ud558\ub298_676c91bc_87c5174d", "generatedBy": "gpt-5.1", "rawRecordPreserved": true}}','gpt-5.1',NULL,'2026-05-12T07:57:56.387033+00:00',NULL);
INSERT INTO student_support_profiles VALUES('support_profile_draft_student_최하늘_676c91bc_3cc49945','student_최하늘_676c91bc','support_intake_student_최하늘_676c91bc_87c5174d','draft','{"profileVersion": "support_profile_v1", "draftLabel": "\ucd08\uae30 \ud504\ub85c\ud544 v1", "lessonDesignHints": ["\uc218\uc5c5\uc744 \uc2dc\uc791\ud560 \ub54c\ub294 \uc9e7\uc740 \uc608\uc2dc \ubb38\uc81c\ub098 \uc548\ub0b4\ubb38\uc744 \uba3c\uc800 \ubcf4\uc5ec \uc8fc\uace0, \uc608\uc2dc \uc18d \ud575\uc2ec \ub2e8\uc11c\ub97c \uac19\uc774 \uc9da\uc5b4 \ubcf8 \ub4a4 \ubcf8 \ubb38\uc81c\ub85c \ub118\uc5b4\uac11\ub2c8\ub2e4.", "\ubb38\uc81c \uc870\uac74\uc774 \uae38\uc5b4\uc9c8\uc218\ub85d \ubb38\uc7a5\uc744 \ub458\uc774\ub098 \uc14b\uc73c\ub85c \ub098\ub204\uc5b4 \uc81c\uc2dc\ud558\uace0, \ubb38\uc7a5\ub9c8\ub2e4 \uc911\uc694\ud55c \ub0b1\ub9d0\uc5d0 \ubc11\uc904\u00b7\uad75\uac8c \ud45c\uc2dc \ub4f1\uc73c\ub85c \uc2dc\uac01 \ub2e8\uc11c\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.", "\uccab \ubb38\ud56d\uc740 \ub09c\uc774\ub3c4\uac00 \ub0ae\uace0 \uc870\uac74\uc774 \uc9e7\uc740 \ubb38\uc81c\ub85c \uc81c\uc2dc\ud574 \uc548\uc815\uac10\uc744 \uc8fc\uace0, \uc810\ucc28 \uc870\uac74 \uae38\uc774\uc640 \ub2e8\uacc4 \uc218\ub97c \ub298\ub824 \uac00\uba70 \uc5f0\uc2b5\ud569\ub2c8\ub2e4.", "\uc0c8 \uac1c\ub150 \uc124\uba85\uc740 \ud55c \ubc88\uc5d0 \ud55c \uac00\uc9c0 \ud575\uc2ec\ub9cc \ub9d0\ud558\uace0, \u20181\ub2e8\uacc4-2\ub2e8\uacc4-3\ub2e8\uacc4\u2019\ucc98\ub7fc \uc9e7\uc740 \ub2e8\uacc4 \ubb36\uc74c\uc73c\ub85c \uc815\ub9ac\ud574 \uc8fc\ub294 \uad6c\uc870\uac00 \ud6a8\uacfc\uc801\uc785\ub2c8\ub2e4."], "learningResponsePattern": {"worksWell": ["\uc9e7\uc740 \uc608\uc2dc \ubb38\uc81c\ub97c \uba3c\uc800 \ubcf4\uace0 \uac1c\ub150\uc774\ub098 \uaddc\uce59\uc744 \uc774\ud574\ud558\ub294 \ub370 \uac15\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.", "\uc77d\uae30 \ubd84\ub7c9\uc774 \ub108\ubb34 \ub9ce\uc9c0 \uc54a\uc744 \ub54c\ub294 \uc81c\uc2dc\ub41c \uc815\ubcf4\ub97c \uae30\ubc18\uc73c\ub85c \ucc28\uadfc\ucc28\uadfc \ub530\ub77c\uac00\ub294 \ud3b8\uc785\ub2c8\ub2e4.", "\ub2e8\uacc4\uac00 \ubd84\uba85\ud558\uac8c \ub098\ub25c \uc124\uba85\uc774\ub098 \uc608\uc2dc\uc5d0\uc11c\ub294 \uc218\ud589\uc774 \ube44\uad50\uc801 \uc548\uc815\uc801\uc785\ub2c8\ub2e4."], "canBeHard": ["\uc870\uac74 \ubb38\uc7a5\uc774 \uae38\uc5b4\uc9c0\uba74 \ud55c \ubc88\uc5d0 \uc77d\uc744 \ub54c \ud575\uc2ec \ub2e8\uc5b4\ub97c \ub193\uce58\uac70\ub098 \uc804\uccb4 \ub73b\uc744 \ub193\uce58\ub294 \uacbd\uc6b0\uac00 \uc788\uc2b5\ub2c8\ub2e4.", "\uae34 \ubb38\uc81c \uc870\uac74\uc744 \uc77d\uc740 \ub4a4 \uc5b4\ub5a4 \uc815\ubcf4\ubd80\ud130 \uc0ac\uc6a9\ud574\uc57c \ud560\uc9c0 \uc120\ud0dd\ud558\ub294 \ub370\uc11c \ubd80\ub2f4\uc744 \ub290\ub084 \uc218 \uc788\uc2b5\ub2c8\ub2e4.", "\ucc98\uc74c\ubd80\ud130 \uae34 \uc124\uba85\uc774\ub098 \ubcf5\uc7a1\ud55c \uc870\uac74\uc73c\ub85c \uc2dc\uc791\ud558\uba74 \uacfc\uc81c \ucc38\uc5ec\uac00 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4."], "choiceCountLimit": 3, "readingLoad": "medium", "explanationStyle": "\uc9e7\uc740 \uc608\uc2dc\ub97c \uba3c\uc800 \uc81c\uc2dc\ud558\uace0, \uae34 \uc870\uac74\uc740 2~3\uac1c\uc758 \uc9e7\uc740 \ubb38\uc7a5\uacfc \ub2e8\uacc4\ub85c \ub098\ub204\uc5b4 \ucc9c\ucc9c\ud788 \ud655\uc778\ud558\ub294 \uc18d\ub3c4\uac00 \uc801\ud569\ud569\ub2c8\ub2e4."}, "behaviorSupportProfile": {"priorityBehaviors": ["\uae34 \ubb38\uc81c \uc870\uac74\uc744 \uc77d\uc744 \ub54c \ud575\uc2ec \ub2e8\uc11c\ub97c \ub193\uce58\uc9c0 \uc54a\uace0 \ud655\uc778\ud558\uba70 \ud480\uc774\ub97c \uc774\uc5b4 \uac00\uae30"], "functionHypotheses": ["\ubb38\uc81c \uc870\uac74\uc774 \uae38\uac70\ub098 \ubcf5\uc7a1\ud560 \ub54c \uc815\ubcf4\ub7c9\uacfc \ucc98\ub9ac \ubd80\ub2f4\uc774 \ucee4\uc838\uc11c \uacfc\uc81c \ucc38\uc5ec\uac00 \ub290\ub824\uc9c0\uac70\ub098 \ub9c9\ud790 \uc218 \uc788\uc2b5\ub2c8\ub2e4."], "replacementSkills": ["\uae34 \uc870\uac74\uc744 \ubcfc \ub54c \uc904\uc744 \ubc14\uafb8\uc5b4 \uc77d\uac70\ub098 \ubb38\uc7a5\uc744 \ub098\ub204\uc5b4 \ud45c\uc2dc\ud574 \ubcf4\uae30", "\uc870\uac74 \uc18d\uc5d0\uc11c \ud544\uc694\ud55c \uc22b\uc790\ub098 \ub0b1\ub9d0\uc5d0 \ubc11\uc904\uc744 \uae0b\uac70\ub098 \ud45c\uc2dc\ud558\uae30", "\ud480\uc774\ub97c \uc2dc\uc791\ud558\uae30 \uc804 \u2018\uba3c\uc800 \ud560 \uc77c\u2019\uc744 \ud55c \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud574 \ubcf4\uae30", "\uc774\ud574\uac00 \uc548 \ub420 \ub54c \ub2e4\uc2dc \uc124\uba85\ud574 \ub2ec\ub77c\uace0 \uc694\uccad\ud558\uae30", "\uc608\uc2dc \ubb38\uc81c\uc640 \uc9c0\uae08 \ubb38\uc81c\uc758 \uac19\uc740 \uc810\u00b7\ub2e4\ub978 \uc810\uc744 \ud55c \uac00\uc9c0\uc529 \ub9d0\ud574 \ubcf4\uae30"], "recommendedScaffolds": ["\uc644\uc131\ub41c \uc608\uc2dc \ud480\uc774 \uc81c\uc2dc \ud6c4 \ube44\uc2b7\ud55c \ubb38\uc81c\ub85c \ub118\uc5b4\uac00\uae30", "\uae34 \uc870\uac74\uc744 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub098\ub204\uc5b4 \uc81c\uc2dc\ud558\uace0 \ud575\uc2ec \ub2e8\uc5b4\ub97c \uc2dc\uac01\uc801\uc73c\ub85c \uac15\uc870\ud558\uae30", "\ubb38\uc81c \uc870\uac74\uc758 \ud575\uc2ec \ub2e8\uc11c\ub97c 2~3\uac1c bullet\ub85c \ub530\ub85c \uc815\ub9ac\ud574 \uc8fc\uae30", "\ud480\uc774 \uc21c\uc11c\ub97c 1\ubc88, 2\ubc88, 3\ubc88 \ub2e8\uacc4 \uce74\ub4dc\ub098 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub85c \uc81c\uacf5\ud558\uae30", "\uc120\ud0dd\uc9c0\ub294 3\uac1c \uc548\uc5d0\uc11c \uc81c\uc2dc\ud558\uace0, \uc624\ub2f5\uc740 \ud575\uc2ec \ub2e8\uc11c\ub97c \ud558\ub098\uc529 \ube7c\uac70\ub098 \ubc14\uafbc \ud615\ud0dc\ub85c \uad6c\uc131\ud558\uae30", "\uccab \ubb38\ud56d\uc740 \uc9e7\uc740 \uc870\uac74\uacfc \uc26c\uc6b4 \ub09c\uc774\ub3c4\ub85c \uc81c\uc2dc\ud574 \uc131\uacf5 \uacbd\ud5d8\uc744 \uba3c\uc800 \ud655\ubcf4\ud558\uae30"]}, "strengths": ["\uc9e7\uc740 \uc608\uc2dc \ubb38\uc81c\ub098 \uc548\ub0b4\ubb38\uc744 \uba3c\uc800 \ubcf4\uc5ec \uc8fc\uba74 \uac1c\ub150\uacfc \uaddc\uce59\uc744 \uc774\ud574\ud558\ub294 \uc18d\ub3c4\uac00 \ube60\ub978 \ud3b8\uc785\ub2c8\ub2e4.", "\ub2e8\uacc4\uac00 \ubd84\uba85\ud558\uac8c \ub098\ub258\uc5b4 \uc788\ub294 \uc124\uba85\uc5d0\uc11c\ub294 \uc81c\uc2dc\ub41c \uc21c\uc11c\ub97c \ub530\ub77c\uac00\uba70 \uc218\ud589\uc744 \uc774\uc5b4 \uac08 \uc218 \uc788\uc2b5\ub2c8\ub2e4.", "\uc77d\uae30 \ubd84\ub7c9\uc774 \uc801\uc808\ud560 \ub54c\ub294 \uc2a4\uc2a4\ub85c \ub2e4\uc2dc \uc124\uba85\uc744 \uc694\uccad\ud558\uba70 \uacfc\uc81c\ub97c \uc774\uc5b4 \uac00\ub824\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc785\ub2c8\ub2e4."], "supportCautions": ["\ud55c \ubc88\uc5d0 \uae34 \uc870\uac74\uc744 \uc77d\uac8c \ud558\uba74 \ud575\uc2ec \ub2e8\uc5b4\ub97c \ub193\uccd0 \ubb38\uc81c \uc774\ud574\uc5d0\uc11c \ub9c9\ud790 \uc218 \uc788\uc5b4, \ubb38\uc7a5\uc744 \ub098\ub204\uc5b4 \uc81c\uc2dc\ud558\ub294 \ud3b8\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.", "\uc218\uc5c5\uc744 \uae34 \uc124\uba85\uc73c\ub85c \uc2dc\uc791\ud558\uba74 \uc9d1\uc911\uacfc \uc774\ud574 \ubaa8\ub450\uc5d0\uc11c \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uc218 \uc788\uc5b4, \uc26c\uc6b4 \uccab \ubb38\ud56d\uacfc \uc608\uc2dc \uc81c\uc2dc \ud6c4 \ubcf8 \ud559\uc2b5\uc73c\ub85c \uc5f0\uacb0\ud558\ub294 \uad6c\uc131\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.", "\uae34 \ubb38\uc81c \uc870\uac74\uc744 \ub2e4\ub8e8\ub294 \ud65c\ub3d9\uc5d0\uc11c\ub294 \ud575\uc2ec \ub2e8\uc11c \ud45c\uc2dc, \ub2e8\uacc4 \ub098\ub204\uae30 \uac19\uc740 \uc804\ub7b5\uc744 \ud568\uaed8 \uc9c0\ub3c4\ud558\uc9c0 \uc54a\uc73c\uba74 \uc815\ub2f5\uc5d0 \ub3c4\ub2ec\ud558\uae30\uae4c\uc9c0 \uc2dc\uac04\uc774 \uc624\ub798 \uac78\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4."], "source": {"intakeSourceId": "support_intake_student_\ucd5c\ud558\ub298_676c91bc_87c5174d", "generatedBy": "gpt-5.1", "rawRecordPreserved": true}}','gpt-5.1',NULL,'2026-05-12T11:16:43.388803+00:00',NULL);
INSERT INTO student_support_profiles VALUES('support_profile_draft_student_최하늘_676c91bc_5d82a869','student_최하늘_676c91bc','support_intake_student_최하늘_676c91bc_87c5174d','draft','{"profileVersion": "support_profile_v1", "draftLabel": "\ucd5c\ucd08 \uc0dd\uc131 \ud504\ub85c\ud544", "lessonDesignHints": ["\ub3c4\uc785\uc5d0\uc11c\ub294 \uae34 \uc124\uba85 \ub300\uc2e0 \uc9e7\uc740 \uc608\uc2dc \ubb38\uc81c\ub098 \uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \ud568\uaed8 \ubcf4\uba70 \uc624\ub298 \ud560 \ud65c\ub3d9 \uad6c\uc870\ub97c \ubcf4\uc5ec \uc8fc\uc138\uc694.", "\ubb38\uc81c \uc870\uac74\uc774\ub098 \uc548\ub0b4\ubb38\uc740 1~2\ubb38\uc7a5\uc529 \ub04a\uc5b4 \uc81c\uc2dc\ud558\uace0, \uac01 \ub369\uc5b4\ub9ac\ub9c8\ub2e4 \ub204\uac00\u00b7\uc5b8\uc81c\u00b7\ubb34\uc5c7\uc744 \ud558\ub294\uc9c0 \ud575\uc2ec \ub2e8\uc11c\ub97c \ud568\uaed8 \ud45c\uc2dc\ud574 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uccab \ubb38\ud56d\uc740 \ub09c\uc774\ub3c4\ub97c \ub0ae\ucd94\uc5b4 \uc131\uacf5 \uacbd\ud5d8\uc744 \uc8fc\uace0, \uc774\ud6c4 \ubb38\ud56d\uc5d0\uc11c\ub9cc \uc870\uac74\uc744 \uc870\uae08\uc529 \ub298\ub9ac\uba70 \uac19\uc740 \uad6c\uc870\ub85c \uc5f0\uc2b5\uc744 \ubc18\ubcf5\ud574 \uc8fc\uc138\uc694.", "\uc124\uba85\uc774 \uc5b4\ub824\uc6cc \ubcf4\uc77c \ub54c\ub294 \ud559\uc0dd\uc774 \u2018\ub2e4\uc2dc \uc124\uba85\ud574 \ub2ec\ub77c\u2019\uace0 \uc694\uccad\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \ubbf8\ub9ac \uc548\ub0b4\ud558\uace0, \uc694\uccad\uc774 \ub098\uc624\uba74 \ub354 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \uc7ac\uc815\ub9ac\ud574 \uc8fc\uc138\uc694."], "learningResponsePattern": {"worksWell": ["\uc9e7\uc740 \uc608\uc2dc \ubb38\uc81c\ub098 \uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \ubcf4\uba74 \uc774\ud574\uac00 \ube60\ub985\ub2c8\ub2e4.", "\uc77d\uae30 \ubd80\ub2f4\uc774 \ud06c\uc9c0 \uc54a\uc740 \uc870\uac74\uc5d0\uc11c\ub294 \uc548\ub0b4\ub97c \ub530\ub77c\uac00\uba70 \ud65c\ub3d9\uc744 \uc644\uc218\ud569\ub2c8\ub2e4.", "\uc26c\uc6b4 \uccab \ubb38\ud56d\uc774 \uc81c\uc2dc\ub418\uba74 \uc815\uc11c\uc801\uc73c\ub85c \uc548\uc815\ub418\uc5b4 \ub05d\uae4c\uc9c0 \ucc38\uc5ec\ud569\ub2c8\ub2e4.", "\uc9e7\uc740 \uc548\ub0b4 \ud6c4 \ub2e8\uacc4 \ub098\ub204\uae30 \ud65c\ub3d9\uc5d0\ub294 \ud765\ubbf8\ub97c \ubcf4\uc774\uba70 \u2018\uc7ac\ubbf8\uc788\ub2e4\u2019\uace0 \ud68c\uace0\ud569\ub2c8\ub2e4."], "canBeHard": ["\uae34 \ubb38\uc81c \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \uc77d\uc744 \ub54c \ud575\uc2ec \ub2e8\uc5b4\ub97c \ub193\uce58\uace0 \uc624\ub2f5\uc774 \ub098\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4.", "\uc870\uac74\uc744 2~3\ub2e8\uacc4\ub85c \uc815\ud655\ud788 \ub098\ub204\uc5b4 \uc815\ub9ac\u00b7\uc124\uba85\ud558\ub294 \uc774\ud574\uac00 \uc544\uc9c1 \ubd88\uc644\uc804\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.", "\uc2e4\uc2dc\uac04 \ub9d0\ud558\uae30 \ub2e8\uacc4\uc5d0\uc11c\ub294 \ubc1c\ud654\uac00 \ucda9\ubd84\ud788 \ub098\uc624\uc9c0 \uc54a\uc544 \uc774\ud574 \uc218\uc900 \ud655\uc778\uc774 \uc5b4\ub824\uc6b8 \ub54c\uac00 \uc788\uc2b5\ub2c8\ub2e4.", "\uc218\uc5c5\uc744 \uae34 \uc124\uba85\uc73c\ub85c \uc2dc\uc791\ud558\uba74 \uc9d1\uc911\uc774 \ub5a8\uc5b4\uc9c0\uac70\ub098 \ub0b4\uc6a9\uc744 \ub530\ub77c\uac00\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4."], "choiceCountLimit": 3, "readingLoad": "medium", "explanationStyle": "\uc9e7\uc740 \uc608\uc2dc \uc81c\uc2dc \u2192 \uc870\uac74\uc744 1~2\ubb38\uc7a5\uc529 \ub04a\uc5b4 \uc77d\uc73c\uba70 \ud575\uc2ec \ub2e8\uc11c\ub97c \ud45c\uc2dc \u2192 \u2018\uba3c\uc800-\uadf8\ub2e4\uc74c-\ub9c8\uc9c0\ub9c9\uc73c\ub85c\u2019 \ub4f1 \uc21c\uc11c \ub9d0\ub85c 2~3\ub2e8\uacc4\ub85c \uc815\ub9ac\ud558\uac8c \ud558\ub294 \uc18d\ub3c4\ub85c \uc9c4\ud589\ud569\ub2c8\ub2e4."}, "behaviorSupportProfile": {"priorityBehaviors": ["\uae34 \ubb38\uc81c \uc870\uac74\uc744 \uc774\ud574\ud558\uba70 \ud575\uc2ec \ub2e8\uc11c\ub97c \ub193\uce58\uc9c0 \uc54a\uace0 \ucc3e\uae30", "\ud575\uc2ec \ub2e8\uc11c\ub97c \ubc14\ud0d5\uc73c\ub85c \uaddc\uce59\uc774\ub098 \uc808\ucc28\ub97c 2~3\ub2e8\uacc4\ub85c \ub9d0\uc774\ub098 \uae00\ub85c \uc815\ub9ac\ud558\uae30"], "functionHypotheses": ["\uae34 \uae00\uc774\ub098 \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \uc81c\uc2dc\ud558\uba74 \uc815\ubcf4\ub7c9\uc774 \ub9ce\uc544 \ud575\uc2ec \ub2e8\uc11c \ud30c\uc545\uc774 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\uc5b4, \uc870\uac74\uc744 \ubd84\ud560\ud558\uace0 \uc2dc\uac01\uc801\uc73c\ub85c \uc815\ub9ac\ud558\ub294 \uad6c\uc870\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.", "\ub9d0\ud558\uae30 \ud65c\ub3d9\uc5d0\uc11c\ub294 \ubb34\uc5c7\ubd80\ud130 \ub9d0\ud560\uc9c0 \ub9dd\uc124\uc774\uba70 \uba48\ucd9c \uc218 \uc788\uc5b4, \ub2e4\uc74c\uc5d0 \ub9d0\ud560 \ud55c \ub2e8\uacc4\ub9cc \ub5a0\uc62c\ub9ac\uac8c \ub3d5\ub294 \ubc1c\ubb38\uacfc \uae30\ub2e4\ub824 \uc8fc\uae30\uac00 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4."], "replacementSkills": ["\ubb38\uc81c\ub098 \uc124\uba85\uc774 \uc5b4\ub835\uac8c \ub290\uaef4\uc9c8 \ub54c \u2018\ub2e4\uc2dc \ud55c \ubc88 \uc9e7\uac8c \uc124\uba85\ud574 \uc8fc\uc138\uc694\u2019\ub77c\uace0 \uc694\uccad\ud558\uae30", "\uc870\uac74 \ubb38\uc7a5\uc744 \uc77d\uc73c\uba70 \uc911\uc694\ud55c \ub0b1\ub9d0\uc5d0 \ubc11\uc904\uc774\ub098 \ud45c\uc2dc\ub97c \ud574 \ub450\uae30(\ud575\uc2ec \ub2e8\uc11c \ud45c\uc2dc\ud558\uae30)", "\uc870\uac74\uc5d0\uc11c \ucc3e\uc740 \ud575\uc2ec \ub2e8\uc11c\ub97c \ud1a0\ub300\ub85c \ud480\uc774 \uc21c\uc11c\ub97c \u2018\uba3c\uc800-\uadf8\ub2e4\uc74c-\ub9c8\uc9c0\ub9c9\uc73c\ub85c\u2019 \ub4f1 \uc21c\uc11c \ub9d0\uc744 \ub123\uc5b4 \ub9d0\ud558\uac70\ub098 \uc801\uc5b4 \ubcf4\uae30", "\uc608\uc2dc\uc640 \uc0c8 \ubb38\uc81c\ub97c \ube44\uad50\ud558\uba70 \uac19\uc740 \uc810\u00b7\ub2e4\ub978 \uc810\uc744 \ud55c \uac00\uc9c0\uc529 \ub9d0\ud574 \ubcf4\uae30", "\uc815\ub2f5\uc744 \uc120\ud0dd\ud55c \ub4a4, \uadf8 \uc774\uc720\ub97c \ud55c \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud574 \ubcf4\uba70 \uc2a4\uc2a4\ub85c \ud655\uc778\ud558\uae30"], "recommendedScaffolds": ["\uc608\uc2dc \ubb38\uc81c\u00b7\uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \uc81c\uc2dc\ud55c \ub4a4 \uc720\uc0ac \uad6c\uc870\uc758 \ubcf8 \ubb38\uc81c\ub97c \uc81c\uc2dc\ud558\uae30", "\ubb38\uc81c \uc870\uac74\uc744 1~2\ubb38\uc7a5\uc529 \ub098\ub204\uc5b4 \uc81c\uc2dc\ud558\uace0, \ub204\uac00\u00b7\uc5b8\uc81c\u00b7\ubb34\uc5c7\uc744 \ud558\ub294\uc9c0 \ud575\uc2ec \ub2e8\uc11c\ub97c \ub208\uc5d0 \ubcf4\uc774\uac8c \ud45c\uc2dc\ud574 \uc8fc\uae30", "\u2018\uba3c\uc800-\uadf8\ub2e4\uc74c-\ub9c8\uc9c0\ub9c9\uc73c\ub85c\u2019 \ub4f1 \uc21c\uc11c \ub9d0\uce74\ub4dc\ub098 \ubb38\uc7a5\ud2c0\uc744 \uc81c\uacf5\ud558\uc5ec 2~3\ub2e8\uacc4\ub85c \uc694\uc57d\ud558\uac8c \ub3d5\uae30", "\uccab \ubb38\ud56d\uc740 \uae00 \uae38\uc774\uc640 \ub09c\uc774\ub3c4\ub97c \ub0ae\ucd94\uc5b4 \uc131\uacf5 \uacbd\ud5d8\uc744 \uc8fc\uace0, \uc774\ud6c4 \uc870\uac74\uc744 \uc870\uae08\uc529 \ub298\ub9ac\uae30", "\uc120\ud0dd\uc9c0\ub294 3\uac1c \uc548\uc5d0\uc11c \uc81c\uc2dc\ud558\uace0, \uc624\ub2f5\uacfc \uc815\ub2f5\uc758 \ucc28\uc774\uac00 \ub4dc\ub7ec\ub098\ub3c4\ub85d \ud575\uc2ec \ub2e8\uc11c\ub97c \uac15\uc870\ud574 \uc81c\uc2dc\ud558\uae30", "\ud559\uc0dd\uc774 \ub2e4\uc2dc \uc124\uba85\uc744 \uc694\uccad\ud558\uba74 \ud575\uc2ec \ub2e8\uc11c\ub9cc\uc744 \ubaa8\uc544 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \uc7ac\uc124\uba85\ud558\uace0, \uc774\ud574\ud588\ub294\uc9c0 \ud55c \ubb38\uc7a5\uc73c\ub85c \ub530\ub77c \ub9d0\ud574 \ubcf4\uac8c \ud558\uae30"]}, "strengths": ["\uc9e7\uc740 \uc608\uc2dc\ub098 \uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \ubcf4\uba74 \ud65c\ub3d9 \uad6c\uc870\ub97c \ube60\ub974\uac8c \uc774\ud574\ud569\ub2c8\ub2e4.", "\uc77d\uae30 \ubd80\ub2f4\uc774 \ud06c\uc9c0 \uc54a\uace0 \uc608\uc2dc\uac00 \uc81c\uc2dc\ub418\uc5c8\uc744 \ub54c, \ubb38\uc81c\ub97c \ub05d\uae4c\uc9c0 \uc218\ud589\ud558\uba70 \uc644\ub8cc\uc728\uc774 \ub192\uc2b5\ub2c8\ub2e4.", "\uc26c\uc6b4 \uccab \ubb38\ud56d\uc774 \uc8fc\uc5b4\uc9c0\uba74 \uc815\uc11c\uc801\uc73c\ub85c \uc548\uc815\ub418\uc5b4 \uc0c8\ub85c\uc6b4 \ud65c\ub3d9\uc5d0\ub3c4 \uae0d\uc815\uc801\uc73c\ub85c \ucc38\uc5ec\ud569\ub2c8\ub2e4.", "\uaddc\uce59\uc774\ub098 \ub2e8\uacc4 \ub098\ub204\uae30 \ud65c\ub3d9\uc5d0 \ub300\ud574 \u2018\uc7ac\ubbf8\uc788\ub2e4\u2019\uace0 \ud68c\uace0\ud558\ub294 \ub4f1 \ud559\uc2b5 \uacbd\ud5d8\uc744 \uae0d\uc815\uc801\uc73c\ub85c \ubc1b\uc544\ub4e4\uc785\ub2c8\ub2e4."], "supportCautions": ["\uae34 \ubb38\uc81c \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \uc81c\uc2dc\ud558\uba74 \ud575\uc2ec \ub2e8\uc11c\ub97c \ub193\uce58\uace0 \uc624\ub2f5\uc774 \ub098\uc62c \uc218 \uc788\uc5b4, \uc870\uac74 \ubd84\ud560\uacfc \ub2e8\uc11c \ud45c\uc2dc\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.", "\uc218\uc5c5 \ub3c4\uc785\uc744 \uae34 \uc124\uba85\uc73c\ub85c \uc2dc\uc791\ud558\uba74 \uc9d1\uc911\uc774 \ub5a8\uc5b4\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c, \uc9e7\uc740 \uc608\uc2dc\uc640 \uc26c\uc6b4 \uccab \ubb38\ud56d\uc73c\ub85c \uc2dc\uc791\ud558\ub294 \uad6c\uc131\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.", "\ub9d0\ud558\uae30 \ub2e8\uacc4\uc5d0\uc11c \ubc1c\ud654\uac00 \uc801\uc744 \uc218 \uc788\uc5b4, \ud3c9\uac00\ubcf4\ub2e4\ub294 \uc5f0\uc2b5\uc73c\ub85c \ubcf4\uace0 \ud55c \ub2e8\uacc4\uc529 \ub9d0\ud574 \ubcfc \uc218 \uc788\ub3c4\ub85d \uae30\ub2e4\ub824 \uc8fc\ub294 \ud3b8\uc774 \uc88b\uc2b5\ub2c8\ub2e4.", "\ud575\uc2ec \ub2e8\uc11c\ub97c \ubc14\ud0d5\uc73c\ub85c 2~3\ub2e8\uacc4\ub85c \uc815\ud655\ud788 \ub098\ub204\uc5b4 \uc815\ub9ac\ud558\ub294 \ub2a5\ub825\uc740 \uc544\uc9c1 \ud615\uc131 \uc911\uc774\ubbc0\ub85c, \uac11\uc791\uc2a4\ub7ec\uc6b4 \ub09c\uc774\ub3c4 \uc0c1\uc2b9\uc740 \ud53c\ud558\uace0 \uac19\uc740 \uad6c\uc870\ub97c \uc5ec\ub7ec \ub9e5\ub77d\uc5d0\uc11c \ubc18\ubcf5 \uc5f0\uc2b5\ud558\ub294 \ud3b8\uc774 \uc88b\uc2b5\ub2c8\ub2e4."], "source": {"intakeSourceId": "support_intake_student_\ucd5c\ud558\ub298_676c91bc_87c5174d", "generatedBy": "gpt-5.1", "rawRecordPreserved": true}}','gpt-5.1',NULL,'2026-05-12T11:24:24.318907+00:00',NULL);
INSERT INTO student_context_briefs VALUES('context_brief_student_김진수_daa552f0_79465ef4','student_김진수_daa552f0','김진수 학생은 짧은 첫 과제 같은 강점이 관찰됩니다. 이전 수업과 관찰 기록을 보면 짧은 단서 같은 조건에서 안정적입니다. 읽기 부담은 보통이며, 초기 응답 선택지는 2개 안팎이 적합합니다. 주의할 흐름: 문제에서 핵심 단서 찾기 상황에서 지원이 필요할 수 있어요. 수업 적용 힌트는 선택지를 줄이기입니다. 기억장치는 새 수업 주제를 정하는 값이 아니라, 선생님 요청 주제를 다루는 제시 순서와 반응 방식을 조정하는 값입니다.','학습지원형','medium',2,'[]','["\ubb38\uc81c\uc5d0\uc11c \ud575\uc2ec \ub2e8\uc11c \ucc3e\uae30 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc5b4\uc694."]','["\uc120\ud0dd\uc9c0\ub97c \uc904\uc784"]','[]','2026-05-12T11:12:29.193289+00:00',1,'dirty','{"trigger": "manual_refresh", "reportCount": 0, "lastDirtySource": {"trigger": "new_content_saved", "contentId": "content_student_\uae40\uc9c4\uc218_daa552f0_1778584433_7d5b03d8", "status": "teacher_review"}, "dirtySources": [{"trigger": "new_content_saved", "contentId": "content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_e84af6cc", "status": "teacher_review", "markedAt": "2026-05-12T11:13:51.096039+00:00"}, {"trigger": "new_content_saved", "contentId": "content_student_\uae40\uc9c4\uc218_daa552f0_1778584431_cfc782d1", "status": "teacher_review", "markedAt": "2026-05-12T11:13:51.656594+00:00"}, {"trigger": "new_content_saved", "contentId": "content_student_\uae40\uc9c4\uc218_daa552f0_1778584433_7d5b03d8", "status": "teacher_review", "markedAt": "2026-05-12T11:13:53.652271+00:00"}]}','local_demo_ai','2026-05-12T11:12:29.193289+00:00','2026-05-12T11:12:29.193289+00:00');
INSERT INTO student_context_briefs VALUES('context_brief_student_최하늘_676c91bc_aa98478a','student_최하늘_676c91bc',replace('초3 학습지원형 학생으로, 읽기 부담은 보통 수준이며 선택지는 3개 안팎이 적절합니다. 긴 조건을 한 번에 읽을 때 핵심 단어를 놓치는 경향이 있어, 문제 조건이나 안내문을 짧게 나누어 제시하고 핵심 단서를 먼저 함께 확인하는 구성이 필요합니다.\n\n강점: 짧은 예시를 먼저 보면 이해가 빠르며, 쉬운 첫 문항이 제시될 때 정서적으로 안정됩니다. 실시간 말하기 활동에서 ‘재미써요’라고 회고해, 활동 자체에 대한 거부감은 낮은 것으로 보입니다.\n\n어려움 패턴: 긴 문제 조건 이해에서 오답이 나올 가능성이 있고, 말하기 연습에서는 발화가 충분히 나오지 않을 때가 있어 단계 안내와 기다려 주기가 필요합니다.\n\n효과적인 발문·제시 방식: (1) 예시 문제나 예시 문장을 먼저 보여 주기, (2) ‘먼저-그다음-마지막으로’처럼 순서를 나누어 말해 보게 하기, (3) 한 번에 한 단계씩 질문하며 다음 단계 한 가지만 떠올리게 돕기, (4) 학생이 빠진 핵심 단서를 질문으로 떠올리게 하기. 학생이 이해가 어렵다고 느낄 때는 스스로 ‘다시 설명해 달라’고 요청할 수 있으므로, 이를 긍정적으로 받아 주고 다시 짧게 설명해 주는 구조가 좋습니다.\n\n다음 수업 설계 시: 긴 지문이나 조건은 바로 제시하지 말고, 핵심 단서(예: 인물, 장소, 해야 할 일)를 먼저 표시해 준 뒤 전체를 읽도록 합니다. 첫 문제는 난이도를 낮추어 성공 경험을 주고, 이후 단계에서만 선택지 3개 내에서 난이도를 조정합니다. 직전 수업에서 사용한 ‘바통 이어달리기 규칙 설명’ 상황은 바로 반복하기보다, 다른 주제에 같은 구조(핵심 단서 찾고 2~3단계로 나누어 말하기)를 옮겨 적용하는 데 활용합니다.','\n',char(10)),'학습지원형','medium',3,'["\uc608\uc2dc \ubb38\uc81c\ub97c \uba3c\uc800 \ubcf4\uc5ec \uc8fc\uc5c8\uc744 \ub54c \uc774\ud574\uac00 \ube60\ub984", "\uc26c\uc6b4 \uccab \ubb38\ud56d\uc5d0\uc11c \uc548\uc815\uc801\uc73c\ub85c \ubc18\uc751\ud568", "\uc9e7\uc740 \uc548\ub0b4 \ud6c4 \ub2e8\uacc4 \ub098\ub204\uae30 \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud568"]','["\uae34 \ubb38\uc81c \uc870\uac74\uc744 \ud55c \ubc88\uc5d0 \uc77d\uc744 \ub54c \ud575\uc2ec \ub2e8\uc11c\ub97c \ub193\uce68", "\uc2e4\uc2dc\uac04 \ub9d0\ud558\uae30\uc5d0\uc11c \ubc1c\ud654\uac00 \ucda9\ubd84\ud788 \uae30\ub85d\ub418\uc9c0 \uc54a\uc74c"]','["\uc608\uc2dc \ubb38\uc81c\u00b7\uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \uc81c\uc2dc\ud558\uae30", "\uc870\uac74 \ubb38\uc7a5\uc744 1~2\ubb38\uc7a5\uc529 \ub04a\uc5b4 \uc77d\uae30", "\ud575\uc2ec \ub2e8\uc11c(\ub204\uac00\u00b7\uc5b8\uc81c\u00b7\ubb34\uc5c7\uc744)\ub97c \uba3c\uc800 \ud45c\uc2dc\ud558\uace0 \ud568\uaed8 \ud655\uc778\ud558\uae30", "\u2018\uba3c\uc800-\uadf8\ub2e4\uc74c-\ub9c8\uc9c0\ub9c9\uc73c\ub85c\u2019 \uc21c\uc11c \ub9d0\uce74\ub4dc \ub610\ub294 \ub9d0\ud2c0 \uc81c\uacf5", "\uccab \ubb38\ud56d\uc740 \ub09c\uc774\ub3c4 \ub0ae\ucd94\uc5b4 \uc131\uacf5 \uacbd\ud5d8 \uc8fc\uae30", "\ud559\uc0dd\uc774 \uc694\uccad\ud558\uba74 \ub2e4\uc2dc \uc9e7\uac8c \uc124\uba85\ud574 \uc8fc\uae30"]','["\ubc14\ud1b5 \uc774\uc5b4\ub2ec\ub9ac\uae30 \uaddc\uce59 \uc124\uba85 \uc0c1\ud669\uc744 \uadf8\ub300\ub85c \ubc18\ubcf5 \uc0ac\uc6a9", "\uae34 \uc124\uba85\uc73c\ub85c \uc218\uc5c5\uc744 \uc2dc\uc791\ud558\ub294 \ub3c4\uc785 \ubc29\uc2dd", "\ud55c \ubc88\uc5d0 \ub9ce\uc740 \uc870\uac74\uc774 \ub4e4\uc5b4\uac04 \uace0\ub09c\ub3c4 \ubb38\ud56d\uc744 \uccab \ubb38\uc81c\ub85c \uc81c\uc2dc"]','auto_brief_2026-05-12',1,'dirty','{"trigger": "manual_refresh", "reportCount": 0, "aiGenerated": true, "model": "gpt-5.1", "lastDirtySource": {"trigger": "teacher_report_saved", "teacherReportId": "teacher_report_81d8c83b-c19c-417e-809b-6522223ef4a0"}, "dirtySources": [{"trigger": "teacher_report_saved", "teacherReportId": "teacher_report_81d8c83b-c19c-417e-809b-6522223ef4a0", "markedAt": "2026-05-12T11:21:50.738176+00:00"}]}','gpt-5.1','2026-05-12T11:16:35.559010+00:00','2026-05-12T11:16:35.559010+00:00');
INSERT INTO teacher_report_drafts VALUES('report_draft_c2439cf3-a218-4769-9c3d-4d9fe94bed94','review_5965932c-09ef-4cde-82fe-37293879364f','student_최하늘_676c91bc','content_student_최하늘_676c91bc_1778572714_6d81133c','completed',replace('## 수업 반응\n\n> 짧은 안내와 예시 후 끝까지 참여했고, 규칙 나누기 자체는 ‘재미있다’고 회고했습니다.\n\n- 수행 수치: 완료율 100%, 정답률 67%로 4단계 활동을 모두 마무리했습니다.  \n- 정서 반응: 학생 회고에서 “재미써요”라고 응답해 규칙 설명 활동에 대한 긍정 반응이 확인됩니다.  \n- 발화/행동 기록: 실시간 말하기 단계에서 학생 발화가 분리 기록되지 않아, 실제 설명 말하기 행동은 추가 확인이 필요합니다.  \n\n## 이해 변화\n\n> 예시와 단서 표시 후 선택 활동은 수행했으나, 규칙을 2~3단계로 정확히 나누는 이해는 아직 일부만 확인됩니다.\n\n- 안정 조건: 예시 문제·예시 문장을 먼저 제시하고, 조건을 짧게 끊어 읽을 때 문항 수행이 가능했던 것으로 확인됩니다.  \n- 전이 조건: 핵심 단서를 바탕으로 한 문장 선택 활동에서는 일부 오답이 있어, 단서 이해가 설명 단계로 완전히 전이되었는지는 불확실합니다.  \n- 확인 필요: 긴 조건을 한 번에 읽을 때 핵심 단서를 놓치는 경향과, 말하기 단계에서의 실제 단계 나누기 능력은 다음 수업에서 추가 확인이 필요합니다.  \n\n## 다음 수업 제안\n\n> 예시 제시와 단서 표시 지원은 유지하고, 학생의 말하기를 한 문장씩 기록하며 단계 나누기 정확도를 점검하는 방향이 적절합니다.\n\n- 유지: 예시 문제·예시 문장을 먼저 제시하고, 조건 문장을 1~2문장씩 끊어 읽는 방식을 유지합니다.  \n- 유지: ‘누가·언제·무엇을’ 핵심 단서를 먼저 표시하고 함께 확인한 뒤, 활동을 시작하는 구조를 반복합니다.  \n- 조정: 말하기 단계에서는 학생이 말한 1번·2번·3번 문장을 한 문장씩 기록해, 단계 나누기와 핵심 단서 반영 여부를 바로 확인합니다.  \n- 확장: 익숙한 놀이 예시 외 다른 상황에서도, “먼저-그다음-마지막으로” 말틀을 사용해 2~3단계 설명을 연습하도록 조정합니다.','\n',char(10)),'["\ub2e4\uc74c \uc218\uc5c5\uc740 \uc608\uc2dc \ubb38\uc81c\u00b7\uc608\uc2dc \ubb38\uc7a5\uc744 \uba3c\uc800 \uc81c\uc2dc\ud558\uae30, \uc870\uac74 \ubb38\uc7a5\uc744 1~2\ubb38\uc7a5\uc529 \ub04a\uc5b4 \uc77d\uae30, \ud575\uc2ec \ub2e8\uc11c(\ub204\uac00\u00b7\uc5b8\uc81c\u00b7\ubb34\uc5c7\uc744)\ub97c \uba3c\uc800 \ud45c\uc2dc\ud558\uace0 \ud568\uaed8 \ud655\uc778\ud558\uae30 \uac19\uc740 \uc9c0\uc6d0 \ubc29\uc2dd\uc744 \uc720\uc9c0\ud558\uba74\uc11c, \uc774\ubc88 \uc218\uc5c5\uc758 \ubaa9\ud45c\ub97c \ub2e4\ub978 \uc0c1\ud669\uc73c\ub85c \uc62e\uaca8 \uc801\uc6a9\ud574 \ubd05\ub2c8\ub2e4."]','["\ub9d0\ud558\uae30 \ub2e8\uacc4\uc5d0\uc11c\ub294 \uc2e4\uc81c \ud559\uc0dd \ubc1c\ud654\ub97c \ub2e4\uc2dc \ud655\uc778\ud558\uae30", "\uc608\uc2dc \ubb38\uc81c\u00b7\uc608\uc2dc \ubb38\uc